//! Closed scalar snapshot capture analysis shared with HIR source lowering.
use super::IterativeVerifier;
use super::binding::{Availability, Binding, CheckedValue};
use super::declared_type::{function_value_scalar_type, function_value_signature};
use super::diagnostics::{error, source_identifier};
use super::scope::{VerifierFrame, VerifierScope};
use crate::ast::program_source::ProgramSource;
use crate::ast::{ClosureParam, Expr, ExprKind, ParamMode, Statement, Type};
use crate::diagnostic::Diagnostic;
use std::collections::{BTreeMap, BTreeSet, HashMap, HashSet};

pub(crate) fn capture_names_scoped(
    program: &dyn ProgramSource,
    params: &[ClosureParam],
    return_type: &Type,
    body: &Expr,
    outer: &BTreeMap<&str, &Type>,
    scope: Option<&crate::ast::Function>,
) -> Result<Vec<String>, Diagnostic> {
    let scalar = |ty: &Type| {
        function_value_scalar_type(ty) || scope.is_some_and(|function| {
        super::generic_collection_profile(function) && matches!(ty, Type::Named { name, arguments } if arguments.is_empty() && function.type_parameters.iter().any(|p| p.name == *name))
    })
    };
    let reject = |message| error(program, "SPX-T288", message, body.span);
    if params.len() > 8
        || !scalar(return_type)
        || params
            .iter()
            .any(|p| !scalar(&p.ty) || !source_identifier(&p.name))
    {
        return Err(reject(
            "closures require zero through eight named scalar parameters and a scalar result",
        ));
    }
    let names = params
        .iter()
        .map(|p| p.name.as_str())
        .collect::<BTreeSet<_>>();
    if names.len() != params.len() {
        return Err(reject("closure parameter names must be unique"));
    }
    enum Item<'a> {
        Expr(&'a Expr, BTreeSet<&'a str>),
        Block(&'a [Statement], usize, &'a Expr, BTreeSet<&'a str>),
    }
    let mut pending = vec![Item::Expr(body, names)];
    let mut captures = BTreeSet::new();
    let mut nodes = 0usize;
    while let Some(item) = pending.pop() {
        nodes += 1;
        if nodes > 4096 {
            return Err(reject("closure scalar body exceeds 4096 analysis nodes"));
        }
        match item {
            Item::Block(statements, next, tail, mut locals) => {
                let Some(statement) = statements.get(next) else {
                    pending.push(Item::Expr(tail, locals));
                    continue;
                };
                match statement {
                    Statement::Let {
                        name,
                        declared,
                        value,
                        ..
                    } => {
                        if declared.as_ref().is_some_and(|ty| !scalar(ty)) {
                            return Err(reject("closure locals must be Copy scalars"));
                        }
                        let prior = locals.clone();
                        locals.insert(name);
                        pending.push(Item::Block(statements, next + 1, tail, locals));
                        pending.push(Item::Expr(value, prior));
                    }
                    Statement::Assign {
                        name, field, value, ..
                    } => {
                        if field.is_some() || !locals.contains(name.as_str()) {
                            return Err(reject("closure snapshots cannot be mutated"));
                        }
                        pending.push(Item::Block(statements, next + 1, tail, locals.clone()));
                        pending.push(Item::Expr(value, locals));
                    }
                    Statement::While {
                        condition, body, ..
                    } => {
                        pending.push(Item::Block(statements, next + 1, tail, locals.clone()));
                        pending.push(Item::Expr(body, locals.clone()));
                        pending.push(Item::Expr(condition, locals));
                    }
                    _ => return Err(reject("closure body contains an unsupported statement")),
                }
            }
            Item::Expr(expression, locals) => match &expression.kind {
                ExprKind::Int(_)
                | ExprKind::Int32(_)
                | ExprKind::Char(_)
                | ExprKind::Uint8(_)
                | ExprKind::Usize(_)
                | ExprKind::Float32(_)
                | ExprKind::Float64(_)
                | ExprKind::Bool(_) => {}
                ExprKind::Var(name) => {
                    if locals.contains(name.as_str()) {
                        continue;
                    }
                    if name == "result" || outer.get(name.as_str()).is_none_or(|ty| !scalar(ty)) {
                        return Err(reject("closures capture only lexical Copy scalar values"));
                    }
                    captures.insert(name.clone());
                    if captures.len() > 8 {
                        return Err(reject(
                            "closure capture inventory exceeds eight scalar snapshots",
                        ));
                    }
                }
                ExprKind::VecConstructor { value, .. } | ExprKind::Unary { value, .. } => {
                    pending.push(Item::Expr(value, locals))
                }
                ExprKind::Binary { left, right, .. } => {
                    pending.push(Item::Expr(right, locals.clone()));
                    pending.push(Item::Expr(left, locals));
                }
                ExprKind::If {
                    condition,
                    then_branch,
                    else_branch,
                } => {
                    pending.push(Item::Expr(else_branch, locals.clone()));
                    pending.push(Item::Expr(then_branch, locals.clone()));
                    pending.push(Item::Expr(condition, locals));
                }
                ExprKind::Block { statements, tail } => {
                    pending.push(Item::Block(statements, 0, tail, locals))
                }
                ExprKind::Call {
                    name,
                    type_arguments,
                    args,
                } => {
                    if locals.contains(name.as_str())
                        || outer.contains_key(name.as_str())
                        || !type_arguments.is_empty()
                        || program
                            .functions()
                            .iter()
                            .find(|f| f.name == *name)
                            .and_then(function_value_signature)
                            .is_none()
                    {
                        return Err(reject(
                            "closure bodies call only ordinary local scalar functions",
                        ));
                    }
                    pending.extend(args.iter().rev().map(|arg| Item::Expr(arg, locals.clone())));
                }
                _ => {
                    return Err(reject(
                        "closure bodies admit scalar expressions only; nested closures and owning values are excluded",
                    ));
                }
            },
        }
    }
    Ok(captures.into_iter().collect())
}

fn scalar_binding(ty: Type) -> Binding {
    Binding {
        contract_local: false,
        traversal_row: None,
        ty,
        mode: ParamMode::Value,
        availability: Availability::Available,
        moved_places: HashMap::new(),
        definitely_partial: HashSet::new(),
        native_unit_discard: false,
        mutable: false,
        active_loans: BTreeSet::new(),
        borrow_origin: None,
    }
}

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn enter_closure(
        &mut self,
        expression: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let ExprKind::Closure {
            params,
            return_type,
            body,
            owning,
            retained: _,
            mutable,
        } = &expression.kind
        else {
            unreachable!()
        };
        if *owning {
            let value = super::owning_closure::check_construction(
                self.program,
                self.current,
                expression,
                return_type,
                body,
                self.allow_moves,
                &mut self.scopes[scope].bindings,
                self.diagnostics,
            );
            self.values.push(value);
            return Ok(());
        }
        if *mutable {
            self.values.push(Some(super::mutable_closure::construction(
                self.program,
                self.current,
                expression,
                &self.scopes[scope].bindings,
            )?));
            return Ok(());
        }
        if let Some(value) = super::borrowed_closure::construction(
            self.program,
            self.current,
            expression,
            &self.scopes[scope].bindings,
        )? {
            self.values.push(Some(value));
            return Ok(());
        }
        if !self.current.type_parameters.is_empty()
            && !super::generic_collection_profile(self.current)
        {
            return Err(error(
                self.program,
                "SPX-T288",
                "anonymous closures inside generic templates are not admitted",
                expression.span,
            ));
        }
        let outer = self.scopes[scope]
            .bindings
            .iter()
            .map(|(name, binding)| (name.as_str(), &binding.ty))
            .collect();
        let names = capture_names_scoped(
            self.program,
            params,
            return_type,
            body,
            &outer,
            Some(self.current),
        )?;
        let mut bindings = HashMap::new();
        for name in names {
            let binding = &self.scopes[scope].bindings[&name];
            if binding.mode != ParamMode::Value || binding.availability != Availability::Available {
                return Err(error(
                    self.program,
                    "SPX-T288",
                    "closure capture is not an available scalar value",
                    expression.span,
                ));
            }
            bindings.insert(name, scalar_binding(binding.ty.clone()));
        }
        for param in params {
            bindings.insert(param.name.clone(), scalar_binding(param.ty.clone()));
        }
        let scope = self.scopes.len();
        self.recovery.fork(None, scope);
        self.scopes.push(VerifierScope {
            bindings,
            local_borrow_count: 0,
        });
        self.frames
            .push(VerifierFrame::ResumeClosure { expression, scope });
        self.frames.push(VerifierFrame::Enter {
            expression: body,
            scope,
        });
        Ok(())
    }
    pub(super) fn resume_closure(
        &mut self,
        expression: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        if scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "closure verifier scope is not the active child",
            ));
        }
        self.scopes.pop();
        let ExprKind::Closure {
            params,
            return_type,
            body,
            ..
        } = &expression.kind
        else {
            unreachable!()
        };
        let value = self.values.pop().flatten();
        if value
            .as_ref()
            .is_some_and(|value| value.ty == *return_type && value.mode == ParamMode::Value)
        {
            self.values.push(Some(CheckedValue::value(Type::Function {
                parameters: params.iter().map(|p| p.ty.clone()).collect(),
                result: Box::new(return_type.clone()),
            })));
        } else {
            if !value.as_ref().is_some_and(|value| {
                !value.native_unit
                    && value.mode == ParamMode::Value
                    && self.recovery.explains(body, return_type)
            }) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T288",
                    "closure result does not match its scalar signature",
                    expression.span,
                ));
            }
            self.values.push(None);
        }
        Ok(())
    }
}

#[cfg(test)]
#[allow(clippy::too_many_arguments)]
pub(super) fn oracle(
    program: &dyn ProgramSource,
    current: &crate::ast::Function,
    expression: &Expr,
    outer: &HashMap<String, Binding>,
    functions: &HashMap<&str, &crate::ast::Function>,
    types: &super::type_table::TypeTable<'_>,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    if matches!(expression.kind, ExprKind::Closure { mutable: true, .. }) {
        return match super::mutable_closure::construction(program, current, expression, outer) {
            Ok(value) => Some(value),
            Err(error) => {
                diagnostics.push(error);
                None
            }
        };
    }
    match super::borrowed_closure::construction(program, current, expression, outer) {
        Ok(Some(value)) => return Some(value),
        Err(error) => {
            diagnostics.push(error);
            return None;
        }
        Ok(None) => {}
    }
    let ExprKind::Closure {
        params,
        return_type,
        body,
        owning: _,
        retained: _,
        mutable: _,
    } = &expression.kind
    else {
        unreachable!()
    };
    if !current.type_parameters.is_empty() && !super::generic_collection_profile(current) {
        diagnostics.push(error(
            program,
            "SPX-T288",
            "anonymous closures inside generic templates are not admitted",
            expression.span,
        ));
        return None;
    }
    let outer_types = outer
        .iter()
        .map(|(name, binding)| (name.as_str(), &binding.ty))
        .collect();
    let names = match capture_names_scoped(
        program,
        params,
        return_type,
        body,
        &outer_types,
        Some(current),
    ) {
        Ok(names) => names,
        Err(error) => {
            diagnostics.push(error);
            return None;
        }
    };
    let mut bindings = HashMap::new();
    for name in names {
        let binding = &outer[&name];
        if binding.mode != ParamMode::Value || binding.availability != Availability::Available {
            diagnostics.push(error(
                program,
                "SPX-T288",
                "closure capture is not an available scalar value",
                expression.span,
            ));
            return None;
        }
        bindings.insert(name, scalar_binding(binding.ty.clone()));
    }
    for param in params {
        bindings.insert(param.name.clone(), scalar_binding(param.ty.clone()));
    }
    let value = super::oracle::check_expr(
        program,
        current,
        body,
        &mut bindings,
        functions,
        types,
        None,
        true,
        diagnostics,
    );
    if value
        .as_ref()
        .is_some_and(|value| value.ty == *return_type && value.mode == ParamMode::Value)
    {
        Some(CheckedValue::value(Type::Function {
            parameters: params.iter().map(|param| param.ty.clone()).collect(),
            result: Box::new(return_type.clone()),
        }))
    } else {
        diagnostics.push(error(
            program,
            "SPX-T288",
            "closure result does not match its scalar signature",
            expression.span,
        ));
        None
    }
}

pub(super) fn source_signature(params: &[ClosureParam], result: &Type) -> Type {
    Type::Function {
        parameters: params
            .iter()
            .map(|parameter| parameter.ty.clone())
            .collect(),
        result: Box::new(result.clone()),
    }
}

/// Validate authored template closure boundaries before concrete specialization.
/// This check carries no capture/type authority; normal source checking still
/// checks each scalar substitution and its lexical snapshot inventory.
pub(super) fn validate_generic_syntax(
    program: &dyn ProgramSource,
    function: &crate::ast::Function,
) -> Result<(), Diagnostic> {
    if function.type_parameters.is_empty() {
        return Ok(());
    }
    let mut pending = vec![(&function.body, false)];
    while let Some((expression, in_closure)) = pending.pop() {
        if let ExprKind::Closure { owning: true, .. } = &expression.kind {
            return Err(error(
                program,
                "SPX-T291",
                "owning-capture closures are not admitted inside a generic function",
                expression.span,
            ));
        }
        if let ExprKind::Closure {
            params,
            return_type,
            body,
            owning: false,
            retained: false,
            mutable: false,
        } = &expression.kind
        {
            let scalar = |ty: &Type| {
                function_value_scalar_type(ty)
                    || matches!(ty, Type::Named { name, arguments } if arguments.is_empty() && function.type_parameters.iter().any(|parameter| parameter.name == *name))
            };
            if in_closure
                || !super::generic_collection_profile(function)
                || params.len() > 8
                || !scalar(return_type)
                || params.iter().any(|param| !scalar(&param.ty))
            {
                return Err(error(
                    program,
                    "SPX-T288",
                    "generic scalar collection closures cannot be nested",
                    expression.span,
                ));
            }
            pending.push((body, true));
            continue;
        }
        if in_closure {
            match &expression.kind {
                ExprKind::Int(_)
                | ExprKind::Int32(_)
                | ExprKind::Char(_)
                | ExprKind::Uint8(_)
                | ExprKind::Usize(_)
                | ExprKind::Float32(_)
                | ExprKind::Float64(_)
                | ExprKind::Bool(_)
                | ExprKind::Var(_)
                | ExprKind::Unary { .. }
                | ExprKind::Binary { .. }
                | ExprKind::Block { .. }
                | ExprKind::If { .. } => {}
                ExprKind::Call {
                    name,
                    type_arguments,
                    ..
                } if type_arguments.is_empty()
                    && program
                        .functions()
                        .iter()
                        .find(|candidate| candidate.name == *name)
                        .and_then(function_value_signature)
                        .is_some() => {}
                _ => {
                    return Err(error(
                        program,
                        "SPX-T288",
                        "generic closure bodies require ordinary scalar expressions and calls",
                        expression.span,
                    ));
                }
            }
        }
        let mut index = 0;
        while let Some(child) = expression.child(index) {
            pending.push((child, in_closure));
            index += 1;
        }
    }
    Ok(())
}

/// Every admitted collection substitution must be checked, including unused
/// templates. Unsupported specialization must never erase validation work.
pub(super) fn specialize_checked(
    program: &dyn ProgramSource,
    template: &crate::ast::Function,
    arguments: &[Type],
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<crate::ast::Function> {
    let specialized = super::declared_type::validation_specialize_function(template, arguments);
    if specialized.is_none() && super::generic_collection_profile(template) {
        diagnostics.push(error(
            program,
            "SPX-T288",
            "generic collection template cannot be checked for every scalar substitution",
            template.span,
        ));
    }
    specialized
}

pub(super) fn scoped_scalar(function: &crate::ast::Function, ty: &Type) -> bool {
    function_value_scalar_type(ty)
        || (super::generic_collection_profile(function)
            && matches!(ty, Type::Named { name, arguments } if arguments.is_empty() && function.type_parameters.iter().any(|parameter| parameter.name == *name)))
}

//! Whole original verifier/type-table receivers and constructor lifetime controls.
use super::*;
use crate::ast::TypeDeclaration;
use crate::source_verify::private_names::{PrivateNames, Providers};
use crate::test_allocation_observer::measure;
#[rustfmt::skip]
mod corpus;
fn json(diagnostics: &[Diagnostic]) -> Vec<String> {
    diagnostics.iter().map(Diagnostic::json).collect()
}
fn verify(program: &dyn ProgramSource) -> Vec<Diagnostic> {
    let current = super::verify(program);
    let old = declaration::old::verify(program);
    assert_eq!(json(&current), json(&old));
    assert_eq!(
        current.first().map(Diagnostic::json),
        old.first().map(Diagnostic::json)
    );
    current
}
fn compare_public_source(source: &str) {
    let program = crate::parse(source, "constructor-full-public.spx").unwrap();
    let before = program.clone();
    let _ = verify(&program);
    assert_eq!(program, before);
}
const GENERIC: &str = r#"module constructor.generic;
@id("packet") record Packet { @id("packet.n") n:i64, }
@id("identity") fn identity<T>(value:T)->T {value}
@id("relay") fn relay<A,B>(left:A,right:B)->A {identity(left)}
@id("probe") fn probe(n:i64)->i64 requires n>=0 ensures result>=0 {identity(n)}
@id("main") fn main()->i64 {relay(1,true)}
"#;
const FIELDS: &str = r#"module constructor.fields;
@id("packet.a") record Packet { @id("packet.x.a") x:i64, @id("packet.x.b") x:bool, }
@id("packet.b") record Packet { @id("packet.x.c") x:bool, @id("packet.y") y:i64, }
@id("cycle.a") class A:B { @id("a.x") x:i64, }
@id("cycle.b") class B:A { @id("b.x") x:bool, }
@id("main") fn main()->i64 {0}
"#;
#[test]
fn complete_old_public_pass_preserves_generic_duplicate_namespace_cycle_and_first_json() {
    for source in [
        GENERIC,
        FIELDS,
        "module t; fn same(x:i64)->i64 {x} fn same<T>(x:T)->T {x} fn main()->i64 {same(1)}",
        "module t; fn recursive<T>(x:T)->T {recursive(x)} fn main()->i64 {0}",
        "module t; fn probe(n:i64,n:bool)->i64 requires n ensures n {0} fn main()->i64 {0}",
        "module t; fn main()->i64 {let x=1; let x=missing; x}",
        "module t; fn main()->i64 {let values=vec_with_capacity<i64>(1usize);vec_len<i64>(values)}",
    ] {
        compare_public_source(source);
    }
    let program = crate::parse(GENERIC, "constructor-partition.spx").unwrap();
    assert_eq!(
        json(&super::verify_partition(&program)),
        json(&declaration::old::verify_partition(&program))
    );
}
#[test]
fn borrowed_field_lookup_keeps_last_field_and_winning_declaration_including_prelude() {
    let mut program = crate::parse(FIELDS, "constructor-fields.spx").unwrap();
    let current = TypeTable::new(&program);
    let old = TypeTable::new_owned_reference(&program);
    for declaration in program
        .types
        .iter()
        .chain(crate::prelude::declarations_for_program(&program))
    {
        let winner = current.declaration(&declaration.name);
        assert_eq!(
            winner.map(|v| v as *const _),
            old.declaration(&declaration.name).map(|v| v as *const _)
        );
        for name in ["x", "y", "missing"] {
            assert_eq!(
                current
                    .declared_field(&declaration.name, name)
                    .map(|v| v as *const _),
                old.declared_field(&declaration.name, name)
                    .map(|v| v as *const _)
            );
        }
    }
    let winner = &program.types[1];
    let TypeDeclarationKind::Record { fields } = &winner.kind else {
        panic!("record");
    };
    assert!(std::ptr::eq(
        current.declared_field("Packet", "x").unwrap(),
        &fields[0]
    ));
    assert_eq!(current.merged_class_fields, old.merged_class_fields);
    assert_eq!(current.class_parents, old.class_parents);
    drop(current);
    drop(old);
    program.types.truncate(1);
    let current = TypeTable::new(&program);
    let TypeDeclarationKind::Record { fields } = &program.types[0].kind else {
        panic!("record");
    };
    assert!(std::ptr::eq(
        current.declared_field("Packet", "x").unwrap(),
        &fields[1]
    ));
    drop(current);
    let mut collision = crate::parse(
        "module t; fn main()->i64 {let values=vec_with_capacity<i64>(1usize);0}",
        "constructor-prelude.spx",
    )
    .unwrap();
    let mut authored = program.types[0].clone();
    authored.name = "Vec".to_owned();
    collision.types.push(authored);
    let current = TypeTable::new(&collision);
    let old = TypeTable::new_owned_reference(&collision);
    assert_eq!(
        current.declaration("Vec").map(|v| v as *const _),
        old.declaration("Vec").map(|v| v as *const _)
    );
    assert!(!std::ptr::eq(
        current.declaration("Vec").unwrap(),
        &collision.types[0]
    ));
}
/// A held closure whose single copy is the last declaration of the program.
struct Held<'a>(&'a TypeDeclaration);
impl Providers for Held<'_> {
    fn provider(&self, index: usize) -> Option<(&str, &TypeDeclaration)> {
        (index == 0).then_some(("held.provider", self.0))
    }
}

const PROVIDER: &str = "module held.provider;

@id(\"copy\")
record Decoded {
    @id(\"copy.n\")
    n: i64,
}

@id(\"zero\")
fn zero() -> i64
{
    0
}
";

// `_spx_layout_0` is an authored declaration below the bound copies; it keeps
// its authored spelling even though it shares the private prefix.
const SYNTHETIC: &str = "module held.caller;

@id(\"authored\")
record _spx_layout_0 {
    @id(\"authored.n\")
    n: i64,
}

@id(\"copy\")
record _spx_layout_1 {
    @id(\"copy.n\")
    n: i64,
}

@id(\"pick\")
fn pick(value: _spx_layout_1, other: _spx_layout_0) -> i64
{
    if value.n == 0 { value } else { other }
}
";

const PRESENTED: &str =
    "`if` branches return different types: Decoded [unimported @id(\"copy\") from held.provider] \
     and _spx_layout_0";
const ORDINARY: &str = "`if` branches return different types: _spx_layout_1 and _spx_layout_0";

#[test]
fn complete_old_private_presentation_keeps_exact_subject_provider_and_authored_spelling() {
    let provider = crate::parse(PROVIDER, "provider.spx").unwrap();
    let program = crate::parse(SYNTHETIC, "caller.spx").unwrap();
    let held = Held(&provider.types[0]);
    let view = PrivateNames::new(&program, &program, program.types.len() - 1, &held);
    let current = super::verify_presenting(&program, Some(view));
    let old = declaration::old::verify_presenting(&program, Some(view));
    assert_eq!(json(&current), json(&old));
    assert_eq!(
        current
            .iter()
            .find(|d| d.code == "SPX-T211")
            .unwrap()
            .message,
        PRESENTED
    );
    let mut generic_private = program.clone();
    let mut generic_program = crate::parse(GENERIC, "generic-private.spx").unwrap();
    generic_private
        .functions
        .append(&mut generic_program.functions);
    let generic_view = PrivateNames::new(
        &generic_private,
        &generic_private,
        generic_private.types.len() - 1,
        &held,
    );
    assert_eq!(
        json(&super::verify_presenting(
            &generic_private,
            Some(generic_view)
        )),
        json(&declaration::old::verify_presenting(
            &generic_private,
            Some(generic_view)
        )),
    );
    let drifted = program.clone();
    let current = super::verify_presenting(&drifted, Some(view));
    let old = declaration::old::verify_presenting(&drifted, Some(view));
    assert_eq!(json(&current), json(&old));
    assert_eq!(
        current
            .iter()
            .find(|d| d.code == "SPX-T211")
            .unwrap()
            .message,
        ORDINARY
    );
    assert_eq!(
        json(&super::verify_presenting(&program, None)),
        json(&declaration::old::verify_presenting(&program, None))
    );
    assert_eq!(
        json(&super::verify(&program)),
        json(&declaration::old::verify(&program))
    );
}
