//! Diagnostic construction for source verification, plus the shared
//! predicates that decide whether an identifier or scalar type is admitted.

use super::binding::{Availability, Binding, CheckedValue};
use super::iterative::check_expr_with_helpers_view;
use super::type_table::TypeTable;
use crate::ast::program_source::ProgramSource;
use crate::ast::{Expr, ExprKind, Function, ParamMode, Span, Type};
use crate::diagnostic::Diagnostic;
use std::collections::{BTreeSet, HashMap, HashSet};

pub(super) fn reject_native_unit_value(
    program: &dyn ProgramSource,
    expression: &Expr,
    value: &CheckedValue,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if value.native_unit && !matches!(expression.kind, ExprKind::Var(_)) {
        diagnostics.push(error(
            program,
            "SPX-B107",
            "Native Rust Interop declaration set is unsupported: scalar value signature required",
            expression.span,
        ));
    }
}

pub(super) fn reject_aggregate_match_result(
    program: &dyn ProgramSource,
    expression: &Expr,
    value: &CheckedValue,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if value.mode == ParamMode::Value && crate::loop_calls::ast_copy_variant(program, &value.ty) {
        return;
    }
    if !matches!(
        value.ty,
        Type::Never
            | Type::I64
            | Type::I32
            | Type::U8
            | Type::Usize
            | Type::Char
            | Type::F32
            | Type::F64
            | Type::Bool
            | Type::String
    ) {
        diagnostics.push(
            error(
                program,
                "SPX-T258",
                "aggregate-valued match arms are outside the executable match profile",
                expression.span,
            )
            .with_help(
                "build the aggregate with `if`, or make the match arms extract scalar values",
            ),
        );
    }
}

/// Owned String Loops v2: a `match` inside a loop condition or body admits a
/// Copy scalar scrutinee or a variant whose every payload is a Copy scalar.
/// HIR validation re-checks the same rule on resolved types.
pub(super) fn reject_loop_match_scrutinee(
    program: &dyn ProgramSource,
    types: &TypeTable<'_>,
    scrutinee: &Expr,
    value: &CheckedValue,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if value.native_unit || is_scalar_source_type(&value.ty) {
        return;
    }
    if let (Type::Named { name, arguments }, Some(cases)) =
        (&value.ty, types.variant_cases(&value.ty))
    {
        let declaration = types.declaration(name);
        if cases.iter().all(|case| {
            case.fields.iter().all(|field| {
                declaration
                    .and_then(|declaration| {
                        TypeTable::substitute_variant_type(declaration, arguments, &field.ty)
                    })
                    .is_some_and(|ty| {
                        is_scalar_source_type(&ty)
                            || super::declared_type::copy_record_collection::admitted(types, &ty)
                    })
            })
        }) {
            return;
        }
    }
    diagnostics.push(error(
        program,
        "SPX-T252",
        crate::loop_calls::match_scrutinee_refusal(&value.ty.to_string()),
        scrutinee.span,
    ));
}

pub(super) fn reject_aggregate_equality(
    program: &dyn ProgramSource,
    types: &TypeTable<'_>,
    expression: &Expr,
    value: &CheckedValue,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if types.payload_free_variant(&value.ty) {
        return;
    }
    if let (Type::Named { name, .. }, Some(cases)) = (&value.ty, types.variant_cases(&value.ty)) {
        let example = cases
            .iter()
            .find(|case| case.fields.is_empty())
            .map(|case| {
                format!(
                    ", e.g. `match value {{ {name}::{} {{}} => true, _ => false, }}`",
                    case.name
                )
            })
            .unwrap_or_default();
        diagnostics.push(
            error(
                program,
                "SPX-T207",
                format!(
                    "equality on variant `{}` requires a non-generic variant whose cases all \
                     carry no payload",
                    value.ty
                ),
                expression.span,
            )
            .with_help(format!("test the case with `match` instead{example}")),
        );
        return;
    }
    if matches!(
        value.ty,
        Type::OnceFunction
            | Type::OnceFunctionI64
            | Type::OnceFunctionI64Pair
            | Type::MutFunctionI64
            | Type::Function { .. }
            | Type::Named { .. }
            | Type::ArrayU8(_)
            | Type::Bytes
    ) {
        diagnostics.push(
            error(
                program,
                "SPX-T207",
                "aggregate equality is outside the executable comparison profile",
                expression.span,
            )
            .with_help("compare the relevant scalar fields or match the aggregate case explicitly"),
        );
    }
}

#[allow(clippy::too_many_arguments)]
pub(super) fn require_bool(
    program: &dyn ProgramSource,
    function: &Function,
    contract: &Expr,
    variables: &HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    diagnostics: &mut Vec<Diagnostic>,
    kind: &str,
) {
    contract.visit_calls(&mut |callee, span| {
        if variables.contains_key(callee) { return; }
        if let Some(target) = functions.get(callee) {
            if !target.effects.is_empty() {
                diagnostics.push(
                    error(
                        program,
                        "SPX-C102",
                        format!(
                            "{kind} on `{}` calls effectful function `{callee}` with effects {{{}}}",
                            function.name,
                            target.effects.join(", ")
                        ),
                        span,
                    )
                    .with_help("contracts must be deterministic and effect-free"),
                );
            }
        }
    });
    let mut contract_variables = variables.clone();
    // No freshness from a body or previous clause enters this contract domain.
    for binding in contract_variables.values_mut() {
        binding.contract_local = false;
    }
    if let Some(ty) = result_type {
        // A provisional owned result is readable only in this postcondition
        // scope. It stays immutable and contract transfers still select O105.
        if ty == &function.return_type
            && (matches!(ty, Type::Bytes | Type::String)
                || matches!(ty, Type::Named { name, arguments }
                if name == "Result" && arguments.as_slice() == [Type::Bytes, Type::Bytes]))
        {
            contract_variables.insert(
                "result".to_owned(),
                Binding {
                    contract_local: false,
                    traversal_row: None,
                    ty: ty.clone(),
                    mode: ParamMode::Own,
                    availability: Availability::Available,
                    moved_places: HashMap::new(),
                    definitely_partial: HashSet::new(),
                    native_unit_discard: false,
                    mutable: false,
                    active_loans: BTreeSet::new(),
                    borrow_origin: None,
                },
            );
        }
    }
    let (contract_value, refusal_view) = check_expr_with_helpers_view(
        program,
        function,
        contract,
        &mut contract_variables,
        functions,
        types,
        result_type,
        false,
        diagnostics,
        None,
        None,
    );
    if let Some(value) = contract_value {
        if value.native_unit {
            reject_native_unit_value(program, contract, &value, diagnostics);
        } else if value.ty != Type::Bool
            && !refusal_view.is_some_and(|view| view.declared == &Type::Bool)
        {
            diagnostics.push(error(
                program,
                "SPX-C101",
                format!("{kind} on `{}` must be bool", function.name),
                contract.span,
            ));
        }
    }
}

pub(super) fn error(
    program: &dyn ProgramSource,
    code: &'static str,
    message: impl Into<String>,
    span: Span,
) -> Diagnostic {
    Diagnostic::error(code, message, span).at_path(program.path())
}

pub(super) fn invalid_stable_id(
    program: &dyn ProgramSource,
    code: &'static str,
    subject: impl Into<String>,
    span: Span,
) -> Diagnostic {
    error(
        program,
        code,
        format!(
            "{} has an invalid stable id; persistent identities forbid NUL",
            subject.into()
        ),
        span,
    )
}

pub(super) fn reject_reserved_host_id(
    program: &dyn ProgramSource,
    stable_id: &str,
    kind: &str,
    span: Span,
    diagnostics: &mut Vec<Diagnostic>,
) {
    if crate::vec_ops::by_id(stable_id).is_some() || stable_id == crate::vec_field::ID {
        diagnostics.push(error(
            program,
            "SPX-S113",
            format!(
                "authored {kind} uses stable ID `{stable_id}`, which is reserved by the compiler-owned vector operations"
            ),
            span,
        ));
    } else if crate::string_ops::by_id(stable_id).is_some() {
        diagnostics.push(error(
            program,
            "SPX-S113",
            format!(
                "authored {kind} uses stable ID `{stable_id}`, which is reserved by the compiler-owned string operations"
            ),
            span,
        ));
    } else if crate::host_io_ops::by_id(stable_id).is_some()
        || crate::command_io_ops::by_id(stable_id).is_some()
    {
        diagnostics.push(error(
            program,
            "SPX-S113",
            format!(
                "authored {kind} uses stable ID `{stable_id}`, which is reserved by the compiler-owned host I/O operations"
            ),
            span,
        ));
    }
}

pub(super) fn source_identifier(value: &str) -> bool {
    let mut chars = value.chars();
    let plain = matches!(chars.next(), Some(first) if first == '_' || first.is_ascii_alphabetic())
        && chars.all(|character| character == '_' || character.is_ascii_alphanumeric());
    plain
        && !matches!(
            value,
            "module"
                | "vec_of"
                | "permit"
                | "resource"
                | "fn"
                | "own"
                | "borrow"
                | "shared"
                | "uses"
                | "requires"
                | "ensures"
                | "let"
                | "if"
                | "else"
                | "true"
                | "false"
                | "result"
        )
}

/// Explicit Mutation v1 admits exactly the checked Copy scalar value types.
pub(crate) fn is_scalar_source_type(ty: &Type) -> bool {
    matches!(
        ty,
        Type::I64
            | Type::I32
            | Type::U8
            | Type::Usize
            | Type::Char
            | Type::F32
            | Type::F64
            | Type::Bool
    )
}

//! The iterative expression verifier's entry point and frame helpers.
//!
//! `IterativeVerifier` itself is declared in the module root, which pins its
//! frame layout. The frame loop lives in [`run`] and the `while` admission
//! rules in [`while_rules`].

use super::IterativeVerifier;
use super::binding::{Binding, CheckedValue};
use super::diagnostics::{error, source_identifier};
use super::hints;
use super::scope::VerifierFrame;
use super::type_table::TypeTable;
use crate::ast::program_source::ProgramSource;
use crate::ast::{Expr, Function, Statement, Type, TypeDeclarationKind};
use crate::diagnostic::Diagnostic;
use std::collections::HashMap;

mod blocks;
mod calls;
mod enter;
mod lexical_exit;
mod match_arms;
mod matching;
mod operators;
mod records;
mod run;
mod while_rules;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    /// Class Inheritance v1: `true` when consuming `child` as `ancestor`
    /// would leave owned child-declared state behind. The suffix is every
    /// effective child field beyond the ancestor prefix length.
    pub(super) fn upcast_discards_owned_state(&self, child: &str, ancestor: &str) -> bool {
        let child_fields = match self.types.merged_class_fields.get(child) {
            Some(fields) => fields.as_slice(),
            None => return false,
        };
        let parent_len = self
            .types
            .merged_class_fields
            .get(ancestor)
            .map(Vec::as_slice)
            .map(|fields| {
                // The ancestor may be parentless: fall back to its declared
                // field count through the declaration itself.
                fields.len()
            })
            .unwrap_or_else(|| {
                self.types
                    .declaration(ancestor)
                    .map(|declaration| match &declaration.kind {
                        TypeDeclarationKind::Class { fields, .. } => fields.len(),
                        _ => 0,
                    })
                    .unwrap_or(0)
            });
        if child_fields.len() < parent_len {
            return true;
        }
        child_fields[parent_len..]
            .iter()
            .any(|field| self.types.needs_drop(&field.ty))
    }

    /// Queue the next block statement (any kind) or fall through to the
    /// block tail after one statement completes.
    #[allow(clippy::too_many_arguments)]
    pub(super) fn advance_block_statement(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
    ) {
        let next = index + 1;
        let Some(next_statement) = statements.get(next) else {
            self.frames.push(VerifierFrame::ResumeBlockTail {
                parent_scope,
                block_scope,
                outer_names,
            });
            self.frames.push(VerifierFrame::Enter {
                expression: tail,
                scope: block_scope,
            });
            return;
        };
        if let Statement::Let {
            name, name_span, ..
        } = next_statement
        {
            if !source_identifier(name) {
                self.diagnostics.push(hints::reserved_local_binding(
                    self.program,
                    name,
                    *name_span,
                ));
            }
        }
        if let Statement::While {
            condition, body, ..
        } = next_statement
        {
            // While statements complete through their own continuation
            // pair; no per-statement value is produced or consumed.
            self.begin_while_statement(
                expression,
                statements,
                tail,
                parent_scope,
                block_scope,
                next,
                outer_names,
                condition,
                body,
            );
            return;
        }
        if let Statement::For {
            item,
            item_span,
            values,
            body,
            ..
        }
        | Statement::ForBorrow {
            item,
            item_span,
            values,
            body,
            ..
        }
        | Statement::ForOwn {
            item,
            item_span,
            values,
            body,
            ..
        } = next_statement
        {
            self.begin_for_statement(
                expression,
                statements,
                tail,
                parent_scope,
                block_scope,
                next,
                outer_names,
                item,
                *item_span,
                values,
                body,
            );
            return;
        }
        self.check_string_replacement_entry(next_statement, block_scope);
        self.note_owned_buffer_reopen(next_statement);
        self.frames.push(VerifierFrame::ResumeBlockStatement {
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index: next,
            outer_names,
            recovery_checkpoint: self.recovery.checkpoint(self.diagnostics),
        });
        self.frames.push(VerifierFrame::Enter {
            expression: next_statement.value(),
            scope: block_scope,
        });
    }

    /// Begin verification of one `while` statement inside the block scope:
    /// run the Bounded While-Loops v1 admission scan once, reject contract
    /// contexts up front, then type-check the condition.
    #[allow(clippy::too_many_arguments)]
    pub(super) fn begin_while_statement(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        condition: &'p Expr,
        body: &'p Expr,
    ) {
        if !self.allow_moves {
            self.diagnostics.push(error(
                self.program,
                "SPX-T253",
                "while statements are not allowed in contract expressions",
                condition.span,
            ));
        }
        self.loop_depth += 1;
        let _ = self.reject_while_disallowed(condition);
        let _ = self.reject_while_disallowed(body);
        let baseline_names = self.scopes[block_scope]
            .bindings
            .keys()
            .cloned()
            .collect::<Vec<_>>();
        let baseline_bindings = self.scopes[block_scope].bindings.clone();
        self.frames.push(VerifierFrame::ResumeWhileBody {
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
            statement_span: condition.span.merge(body.span),
            baseline_names,
            baseline_bindings: baseline_bindings.clone(),
        });
        // The body is an ordinary block in the loop's scope: it verifies
        // with its own child scope after the condition, and
        // ResumeWhileBody discards its value and checks ownership drift.
        self.frames.push(VerifierFrame::Enter {
            expression: body,
            scope: block_scope,
        });
        self.frames.push(VerifierFrame::ResumeWhileCondition {
            condition,
            block_scope,
            baseline_bindings,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: condition,
            scope: block_scope,
        });
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn begin_for_statement(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        item: &'p str,
        item_span: crate::ast::Span,
        values: &'p Expr,
        body: &'p Expr,
    ) {
        self.frames.push(VerifierFrame::ResumeForSource {
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
            item,
            item_span,
            values,
            body,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: values,
            scope: block_scope,
        });
    }
}

#[allow(clippy::too_many_arguments)]
pub(super) fn check_expr_iterative(
    program: &dyn ProgramSource,
    current: &Function,
    expr: &Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &HashMap<&str, &Function>,
    types: &TypeTable<'_>,
    result_type: Option<&Type>,
    allow_moves: bool,
    diagnostics: &mut Vec<Diagnostic>,
) -> Option<CheckedValue> {
    check_expr_with_helpers(
        program,
        current,
        expr,
        variables,
        functions,
        types,
        result_type,
        allow_moves,
        diagnostics,
        None,
        None,
    )
}
#[allow(clippy::too_many_arguments)]
pub(super) fn check_expr_with_helpers<'a, 'p>(
    program: &'p dyn ProgramSource,
    current: &'p Function,
    expr: &'p Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &'p HashMap<&'p str, &'p Function>,
    types: &'p TypeTable<'p>,
    result_type: Option<&'p Type>,
    allow_moves: bool,
    diagnostics: &'a mut Vec<Diagnostic>,
    helpers: Option<&'a dyn crate::loop_calls::byte_writer::SourceHelpers>,
    fused_producer: Option<&'p Expr>,
) -> Option<CheckedValue> {
    check_expr_with_helpers_view(
        program,
        current,
        expr,
        variables,
        functions,
        types,
        result_type,
        allow_moves,
        diagnostics,
        helpers,
        fused_producer,
    )
    .0
}

#[allow(clippy::too_many_arguments)]
pub(super) fn check_expr_with_helpers_view<'a, 'p>(
    program: &'p dyn ProgramSource,
    current: &'p Function,
    expr: &'p Expr,
    variables: &mut HashMap<String, Binding>,
    functions: &'p HashMap<&'p str, &'p Function>,
    types: &'p TypeTable<'p>,
    result_type: Option<&'p Type>,
    allow_moves: bool,
    diagnostics: &'a mut Vec<Diagnostic>,
    helpers: Option<&'a dyn crate::loop_calls::byte_writer::SourceHelpers>,
    fused_producer: Option<&'p Expr>,
) -> (
    Option<CheckedValue>,
    Option<super::recovery::RefusalView<'p>>,
) {
    let initial = std::mem::take(variables);
    let mut verifier = IterativeVerifier::new(
        program,
        current,
        initial,
        functions,
        types,
        result_type,
        allow_moves,
        diagnostics,
    );
    verifier.byte_helpers = helpers;
    verifier.fused_producer = fused_producer;
    let result = verifier.run(expr);
    let refusal = verifier.recovery.view(expr);
    *variables = verifier
        .scopes
        .first_mut()
        .map(|scope| std::mem::take(&mut scope.bindings))
        .unwrap_or_default();
    drop(verifier);
    match result {
        Ok(value) => (value, refusal),
        Err(diagnostic) => {
            diagnostics.push(diagnostic.at_path(program.path()));
            (None, None)
        }
    }
}

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    fn byte_helper_target(&self, target: &Function) -> bool {
        self.byte_helpers.map_or_else(
            || crate::loop_calls::byte_writer::source_target(self.program, target),
            |index| index.target(target),
        )
    }
    pub(in crate::source_verify) fn byte_helper_assignment(
        &self,
        name: &str,
        value: &Expr,
    ) -> bool {
        self.byte_helpers.map_or_else(
            || crate::loop_calls::byte_writer::source_assignment(self.program, name, value),
            |index| index.assignment(name, value),
        )
    }
}

//! Block and `while` frames: statement sequencing, block tails, and the
//! loop-invariance checks a `while` body must satisfy.

use crate::ast::{Expr, ParamMode, Span, Statement, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::IterativeVerifier;
use crate::source_verify::binding::{Availability, Binding};
use crate::source_verify::diagnostics::{error, is_scalar_source_type, reject_native_unit_value};
use crate::source_verify::loans::{
    activate_local_loan, has_active_overlapping_loan, local_borrow_origin,
    mark_value_sources_moved, merge_moved, release_dead_local_loans,
};
use std::collections::{BTreeSet, HashMap, HashSet};

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(in crate::source_verify) fn check_string_replacement_entry(
        &mut self,
        statement: &Statement,
        scope: usize,
    ) {
        if let Statement::Assign {
            name,
            name_span,
            field: None,
            ..
        } = statement
        {
            if let Some(binding) = self.scopes[scope].bindings.get(name) {
                if binding.ty == Type::String && binding.availability != Availability::Available {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O101",
                        "String replacement starts with an unavailable owner",
                        *name_span,
                    ));
                }
            }
        }
    }
    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_block_statement(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        recovery_checkpoint: crate::source_verify::recovery::Checkpoint,
    ) -> Result<(), Diagnostic> {
        #[cfg(test)]
        if self.recovery_legacy {
            return self.recovery_old_frame_resume_block_statement(
                expression,
                statements,
                tail,
                parent_scope,
                block_scope,
                index,
                outer_names,
            );
        }

        let actual = self.values.pop().unwrap_or(None);
        match &statements[index] {
            Statement::Let {
                name,
                name_span,
                mutable,
                declared,
                value,
                ..
            } => {
                if self.scopes[block_scope].bindings.contains_key(name) {
                    self.diagnostics.push(
                        error(
                            self.program,
                            "SPX-T209",
                            format!("local binding `{name}` shadows an existing value"),
                            *name_span,
                        )
                        .with_help(crate::source_verify::hints::SHADOW_HELP),
                    );
                } else if let Some(actual) = actual {
                    if let Some(diagnostic) = crate::source_verify::expression_statement::check(
                        self.program,
                        &statements[index],
                        &actual,
                    ) {
                        self.diagnostics.push(diagnostic);
                    }
                    if matches!(actual.ty, Type::SliceU8 | Type::Str) && *mutable {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T264",
                            format!(
                                "byte-slice alias `{name}` must be immutable and cannot be reassigned"
                            ),
                            *name_span,
                        ));
                    }
                    // Class Inheritance v1: a declared type accepts
                    // the value's exact type or an ancestor class
                    // whose prefix consumes the value cleanly; the
                    // binding carries the declared type.
                    let mut annotation_refused = false;
                    let mut annotation_origin = None;
                    let mut binding_ty = actual.ty.clone();
                    let mut binding_mode = actual.mode;
                    if let Some(declared_ty) = declared {
                        let exact = actual.ty == *declared_ty;
                        let mut upcast = false;
                        if !exact {
                            if let (
                                Type::Named { name: child, .. },
                                Type::Named { name: ancestor, .. },
                            ) = (&actual.ty, declared_ty)
                            {
                                if self.types.class_extends(child, ancestor) {
                                    if self.upcast_discards_owned_state(child, ancestor) {
                                        self.diagnostics.push(error(
                                            self.program,
                                            "SPX-T233",
                                            format!(
                                                "upcast from `{child}` to `{ancestor}` would discard owned state; only cleanup-inert child fields are admitted in this slice"
                                            ),
                                            value.span,
                                        ));
                                    }
                                    upcast = true;
                                }
                            }
                        }
                        if exact || upcast {
                            binding_ty = declared_ty.clone();
                            binding_mode = if matches!(declared_ty, Type::SliceU8 | Type::Str) {
                                ParamMode::Borrow
                            } else if self.types.needs_drop(declared_ty)
                                || declared_ty.is_uniquely_owned()
                            {
                                ParamMode::Own
                            } else {
                                ParamMode::Value
                            };
                        } else {
                            annotation_refused = match declared_ty {
                                Type::Named { name, .. } => self.types.declaration(name).is_some(),
                                Type::I64
                                | Type::I32
                                | Type::Char
                                | Type::U8
                                | Type::Usize
                                | Type::F32
                                | Type::F64
                                | Type::Bool
                                | Type::String
                                | Type::Bytes => true,
                                _ => false,
                            };
                            let diagnostic = if matches!(
                                (&actual.ty, declared_ty),
                                (Type::ArrayU8(_), Type::ArrayU8(_))
                            ) {
                                "SPX-T262"
                            } else {
                                "SPX-T232"
                            };
                            let help = (diagnostic == "SPX-T232")
                                .then(|| {
                                    crate::source_verify::hints::declared_binding_help(
                                        declared_ty,
                                        value,
                                    )
                                })
                                .flatten();
                            if !self.recovery.explains(value, declared_ty) {
                                if annotation_refused {
                                    annotation_origin = Some(self.diagnostics.len());
                                }
                                self.diagnostics.push(crate::source_verify::hints::with_optional_help(
                                error(
                                    self.program,
                                    diagnostic,
                                    format!(
                                        "declared binding type `{}` does not accept value type `{}`",
                                        // Generic validation specialization
                                        // substitutes `let` annotations, so a
                                        // declared type can carry a private copy.
                                        crate::source_verify::private_names::type_name(
                                            self.program,
                                            self.types,
                                            declared_ty
                                        ),
                                        crate::source_verify::private_names::type_name(
                                            self.program,
                                            self.types,
                                            &actual.ty
                                        )
                                    ),
                                    value.span,
                                ),
                                help,
                            ));
                            }
                        }
                    }
                    let contract_local = !self.allow_moves
                        && actual.mode == ParamMode::Own
                        && crate::source_verify::contract_owners::fresh(
                            value,
                            &actual.ty,
                            &self.scopes[block_scope].bindings,
                        );
                    if self.types.needs_drop(&actual.ty) && actual.mode == ParamMode::Own {
                        if self.allow_moves || contract_local {
                            mark_value_sources_moved(
                                self.program,
                                value,
                                &mut self.scopes[block_scope].bindings,
                                self.types,
                                self.diagnostics,
                            );
                        } else {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-O105",
                                "contract expression cannot transfer an owned resource into a local binding",
                                value.span,
                            ));
                        }
                    }
                    let borrow_origin = matches!(binding_ty, Type::SliceU8 | Type::Str)
                        .then(|| {
                            local_borrow_origin(
                                self.program,
                                value,
                                name,
                                *name_span,
                                &self.scopes[block_scope].bindings,
                                self.types,
                            )
                        })
                        .flatten();
                    if let Some(origin) = &borrow_origin {
                        activate_local_loan(&mut self.scopes[block_scope].bindings, origin);
                        self.scopes[block_scope].local_borrow_count += 1;
                    }
                    self.recovery.clear(block_scope, name);
                    self.scopes[block_scope].bindings.insert(
                        name.clone(),
                        Binding {
                            contract_local,
                            traversal_row: None,
                            ty: binding_ty,
                            mode: binding_mode,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: actual.native_unit,
                            mutable: *mutable,
                            active_loans: BTreeSet::new(),
                            borrow_origin,
                        },
                    );
                    // The refusal view is independent of the actual type,
                    // mode, place state, move effects and activated loan above.
                    // A successful explicit annotation provides a fresh type
                    // obligation; an unannotated alias retains the old view.
                    if !actual.native_unit && !*mutable {
                        match (declared, annotation_origin) {
                            (Some(declared), Some(origin)) => self.recovery.refused_annotation(
                                block_scope,
                                name,
                                declared,
                                origin,
                            ),
                            (None, _) => self.recovery.inherit_binding(block_scope, name, value),
                            (Some(declared), None)
                                if annotation_refused
                                    && self.recovery.explains(value, declared) =>
                            {
                                self.recovery.inherit_binding(block_scope, name, value);
                            }
                            _ => {}
                        }
                    }
                } else {
                    self.recovery.refused_let(
                        block_scope,
                        name,
                        recovery_checkpoint,
                        self.diagnostics,
                    );
                }
            }
            Statement::Assign { value, .. } if !self.allow_moves => {
                // Contract expressions stay pure: no stores.
                self.diagnostics.push(error(
                    self.program,
                    "SPX-U106",
                    "assignment statements are not allowed in contract expressions",
                    value.span,
                ));
            }
            Statement::Assign {
                name,
                name_span,
                field,
                value,
                ..
            } => {
                let assigned_projections = field
                    .iter()
                    .map(|field| field.name.clone())
                    .collect::<Vec<_>>();
                let target = self.scopes[block_scope]
                    .bindings
                    .get(name.as_str())
                    .map(|binding| {
                        (
                            binding.mutable,
                            binding.ty.clone(),
                            has_active_overlapping_loan(binding, &assigned_projections),
                        )
                    });
                if target.is_none() {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T202",
                        format!("unknown value `{name}` in `{}`", self.current.name),
                        *name_span,
                    ));
                }
                if let Some((mutable, binding_ty, has_active_loans)) = target {
                    if has_active_loans {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T265",
                            "assignment would replace storage held by a lexical byte view",
                            *name_span,
                        ));
                    }
                    match field {
                        Some(field) => {
                            // Field Mutation v1: one direct scalar
                            // Copy field of a `let mut` record or
                            // class local.
                            if !mutable {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-U107",
                                    format!(
                                        "cannot assign to field of immutable binding `{name}`; declare it with `let mut`"
                                    ),
                                    *name_span,
                                ));
                            }
                            match self.types.record_fields(&binding_ty) {
                                None => {
                                    self.diagnostics.push(error(
                                        self.program,
                                        "SPX-U112",
                                        format!(
                                            "cannot mutate a field of non-record value `{binding_ty}`"
                                        ),
                                        field.span,
                                    ));
                                }
                                Some(fields) => {
                                    let declared = fields
                                        .iter()
                                        .find(|candidate| candidate.name == field.name);
                                    if let Some(declared) = declared {
                                        let field_ty = self
                                            .types
                                            .record_field_type(&binding_ty, declared)
                                            .unwrap_or_else(|| declared.ty.clone());
                                        if !is_scalar_source_type(&field_ty) {
                                            self.diagnostics.push(error(
                                                self.program,
                                                "SPX-U109",
                                                "field mutation v1 supports only direct scalar Copy record fields",
                                                field.span,
                                            ));
                                        }
                                        if let Some(actual) = &actual {
                                            if actual.ty != field_ty {
                                                self.diagnostics.push(error(
                                                    self.program,
                                                    "SPX-U110",
                                                    format!(
                                                        "assigned value type `{}` does not exactly match field type `{}`",
                                                        actual.ty, field_ty
                                                    ),
                                                    value.span,
                                                ));
                                            }
                                        }
                                    } else {
                                        self.diagnostics.push(error(
                                            self.program,
                                            "SPX-U108",
                                            format!(
                                                "record `{binding_ty}` has no field `{}`",
                                                field.name
                                            ),
                                            field.span,
                                        ));
                                    }
                                }
                            }
                        }
                        None => {
                            // The source verifier runs before HIR has the
                            // enclosing `yields Request -> Response` clause
                            // available to retag this direct expression. Its
                            // initial type is therefore the request type;
                            // defer only this whole-binding mismatch to
                            // `finish_yields_admission`, which checks the
                            // binding against the declared response type.
                            // Field assignments and every non-yield value
                            // retain the ordinary exact-type diagnostic here.
                            let direct_yield =
                                matches!(&value.kind, crate::ast::ExprKind::Yield { .. });
                            // Same-owner replacement: a `Vec<T>` reopen such as
                            // `values = vec_push(values, v)` and the byte-buffer
                            // `buffer = bytes_set(buffer, index, value)` and the
                            // Owned String Loops v1 append
                            // `text = string_concat(text, more)` are the
                            // admitted owned reopen shapes. The right-hand side
                            // evaluates before publication, so exactly one
                            // generation of the owner is ever live.
                            let owned_reopen = (binding_ty == crate::ast::Type::Bytes
                                && self.byte_helper_assignment(name, value))
                                || (binding_ty == crate::ast::Type::String
                                    && actual.as_ref().is_some_and(|v| {
                                        v.ty == crate::ast::Type::String && v.mode == ParamMode::Own
                                    }))
                                || crate::vec_ops::is_same_owner_reassignment_source(
                                    self.program,
                                    value,
                                    name,
                                    &binding_ty,
                                )
                                || crate::byte_ops::is_same_owner_set_source(
                                    value,
                                    name,
                                    &binding_ty,
                                )
                                || crate::string_ops::is_same_owner_concat_source(
                                    value,
                                    name,
                                    &binding_ty,
                                )
                                || (self.loop_depth != 0
                                    && self.admits_record_owner_renewal(name, value))
                                || (crate::stdin_stream_ops::ast_is_reader(&binding_ty)
                                    && crate::stdin_stream_ops::source_next_is_same_owner(
                                        self.program,
                                        name,
                                        value,
                                    ));
                            if !mutable {
                                let mut diagnostic = error(
                                    self.program,
                                    "SPX-U101",
                                    format!(
                                        "cannot assign to immutable binding `{name}`; declare it with `let mut`"
                                    ),
                                    *name_span,
                                );
                                if self
                                    .current
                                    .params
                                    .iter()
                                    .any(|parameter| parameter.name == *name)
                                {
                                    diagnostic = diagnostic.with_help(format!(
                                        "parameters are immutable; copy `{name}` into a new mutable local and use that: `let mut current_{name} = {name};`"
                                    ));
                                }
                                self.diagnostics.push(diagnostic);
                            }
                            if let Some(actual) = &actual {
                                if mutable && actual.ty != binding_ty && !direct_yield {
                                    self.diagnostics.push(error(
                                        self.program,
                                        "SPX-U102",
                                        format!(
                                            "assigned value type `{}` does not exactly match binding type `{}`",
                                            actual.ty, binding_ty
                                        ),
                                        value.span,
                                    ));
                                }
                                if mutable
                                    && (actual.mode != ParamMode::Value
                                        || !crate::source_verify::closure::scoped_scalar(
                                            self.current,
                                            &actual.ty,
                                        ))
                                    && !owned_reopen
                                {
                                    self.diagnostics.push(error(
                                        self.program,
                                        "SPX-U105",
                                        "explicit mutation v1 supports only scalar Copy values",
                                        value.span,
                                    ));
                                }
                            }
                            if mutable && owned_reopen {
                                if binding_ty == Type::String
                                    && !crate::string_ops::is_same_owner_concat_source(
                                        value,
                                        name,
                                        &binding_ty,
                                    )
                                {
                                    mark_value_sources_moved(
                                        self.program,
                                        value,
                                        &mut self.scopes[block_scope].bindings,
                                        self.types,
                                        self.diagnostics,
                                    );
                                }
                                if let Some(binding) =
                                    self.scopes[block_scope].bindings.get_mut(name.as_str())
                                {
                                    binding.availability = Availability::Available;
                                    binding.moved_places.clear();
                                    binding.definitely_partial.clear();
                                }
                            }
                        }
                    }
                }
            }
            Statement::Unsafe { body, span, .. } => {
                // Unsafe Boundary Mechanics v1: the module must
                // explicitly permit the `unsafe` capability and
                // the discarded body result must be a scalar Copy
                // value. Contract expressions reject boundaries.
                if !self.allow_moves {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-N105",
                        "unsafe boundary statements are not allowed in contract expressions",
                        *span,
                    ));
                } else {
                    if !self
                        .program
                        .permits()
                        .iter()
                        .any(|permit| permit == "unsafe")
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-N101",
                            "unsafe block requires the module capability declaration `permit { unsafe }`",
                            *span,
                        ));
                    }
                    if let Some(actual) = &actual {
                        if actual.mode != ParamMode::Value || !is_scalar_source_type(&actual.ty) {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-N104",
                                "unsafe boundary bodies must produce a scalar Copy value",
                                body.span,
                            ));
                        }
                    }
                }
            }
            // While statements never route through this frame:
            // they complete through ResumeWhileBody instead.
            Statement::While { .. }
            | Statement::For { .. }
            | Statement::ForBorrow { .. }
            | Statement::ForOwn { .. } => {}
        }
        // Most blocks have no borrowed local at all. Avoid rescanning every
        // accumulated scalar binding after each statement in that common
        // case; the full liveness walk remains exact once a borrow exists.
        if self.scopes[block_scope].local_borrow_count != 0 {
            let released = release_dead_local_loans(
                &mut self.scopes[block_scope].bindings,
                statements.get(index + 1..).unwrap_or_default(),
                tail,
            );
            self.scopes[block_scope].local_borrow_count = self.scopes[block_scope]
                .local_borrow_count
                .saturating_sub(released);
        }
        self.advance_block_statement(
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
        );
        Ok(())
    }

    pub(super) fn frame_resume_while_condition(
        &mut self,
        condition: &'p Expr,
        block_scope: usize,
        baseline: HashMap<String, Binding>,
    ) -> Result<(), Diagnostic> {
        // The condition is re-evaluated before every iteration and
        // must be exactly `bool`.
        let condition_value = self.values.pop().unwrap_or(None);
        if let Some(value) = condition_value {
            if value.native_unit {
                reject_native_unit_value(self.program, condition, &value, self.diagnostics);
            } else if value.ty != Type::Bool && !self.recovery.explains(condition, &Type::Bool) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T251",
                    "`while` condition must be bool",
                    condition.span,
                ));
            }
        }
        let mut names = baseline.keys().collect::<Vec<_>>();
        names.sort();
        for name in names {
            let before = &baseline[name];
            if self.scopes[block_scope]
                .bindings
                .get(name)
                .is_none_or(|now| {
                    now.availability != before.availability
                        || now.moved_places != before.moved_places
                        || now.definitely_partial != before.definitely_partial
                })
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T252",
                    format!("ownership of `{name}` changes inside a while condition"),
                    condition.span,
                ));
            }
        }
        // The body is an ordinary block; it verifies with its own
        // child scope and its value is discarded by
        // ResumeWhileBody.
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_while_body(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        statement_span: Span,
        baseline_names: Vec<String>,
        baseline_bindings: HashMap<String, Binding>,
    ) -> Result<(), Diagnostic> {
        // Discard the body block's value: while statements
        // produce none. The body block merged its own child scope
        // through ResumeBlockTail. Because the v1 admission
        // profile admits only Copy-scalar operations inside the
        // loop, every outer binding must be exactly as available
        // as it was on entry; any drift means a move happened
        // inside the loop and is rejected fail-closed.
        let exits = self
            .values
            .pop()
            .flatten()
            .is_some_and(|value| value.ty == Type::Never);
        if exits && crate::ast::returns_only(statements[index].child(1).expect("while body")) {
            for name in &baseline_names {
                if let Some(before) = baseline_bindings.get(name) {
                    self.scopes[block_scope]
                        .bindings
                        .insert(name.clone(), before.clone());
                }
            }
        }
        self.loop_depth = self.loop_depth.saturating_sub(1);
        for name in &baseline_names {
            let drifted = match (
                self.scopes[block_scope].bindings.get(name),
                baseline_bindings.get(name),
            ) {
                (Some(now), Some(before)) => {
                    now.availability != before.availability
                        || now.moved_places != before.moved_places
                        || now.definitely_partial != before.definitely_partial
                }
                (Some(_), None) | (None, Some(_)) => true,
                (None, None) => false,
            };
            if drifted {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T252",
                    format!(
                        "ownership of `{name}` changes inside a while loop, which is not yet admitted"
                    ),
                    statement_span,
                ));
            }
        }
        let _ = baseline_names;
        release_dead_local_loans(
            &mut self.scopes[block_scope].bindings,
            statements.get(index + 1..).unwrap_or_default(),
            tail,
        );
        self.advance_block_statement(
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
        );
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_for_source(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        item: &'p str,
        item_span: Span,
        values: &'p Expr,
        body: &'p Expr,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let consuming = matches!(statements[index], Statement::ForOwn { .. });
        let borrowing = matches!(statements[index], Statement::ForBorrow { .. });
        let source = match &values.kind {
            crate::ast::ExprKind::Var(name) if !consuming => Some(name.as_str()),
            _ => None,
        };
        let element = actual.as_ref().and_then(|actual| match &actual.ty {
            ty @ Type::SliceU8 if !consuming && !borrowing => {
                crate::source_verify::byte_traversal::element(ty)
            }
            Type::Named { name, arguments }
                if name == (if consuming { "Iter" } else { "Vec" })
                    && matches!(arguments.as_slice(), [ty] if crate::vec_ops::ast_element_is_admitted(ty) && !borrowing
                        || (borrowing && crate::source_verify::record_traversal::admitted(self.types, ty))
                        || (consuming && (*ty == Type::Bytes
                            || crate::source_verify::declared_type::owned_leaf_collection::runtime_element(self.types, ty)
                            || crate::source_verify::declared_type::generic_collection::slot(self.current, &actual.ty))))
                    && (!consuming || actual.mode == ParamMode::Own) => Some(arguments[0].clone()),
            _ => None,
        });
        if (!consuming && source.is_none()) || element.is_none() {
            self.diagnostics.push(error(self.program, "SPX-T284",
                if consuming { "for own traversal requires an owned Iter<T> for an admitted scalar, Bytes, or owned-record T" }
                else { "for traversal requires a simple immutable binding of exact Vec<T> for a Copy scalar T" }, values.span));
        }
        if consuming {
            if !self.allow_moves {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T253",
                    "for own statements are not allowed in contract expressions",
                    values.span,
                ));
            } else if element.is_some() {
                mark_value_sources_moved(
                    self.program,
                    values,
                    &mut self.scopes[block_scope].bindings,
                    self.types,
                    self.diagnostics,
                );
            }
        }
        if let Some(source) = source {
            if self.scopes[block_scope]
                .bindings
                .get(source)
                .is_some_and(|binding| binding.mutable)
            {
                self.diagnostics.push(
                    error(
                        self.program,
                        "SPX-T284",
                        "for traversal source must be an immutable Vec binding",
                        values.span,
                    )
                    .with_help(crate::source_verify::hints::IMMUTABLE_TRAVERSAL_HELP),
                );
            }
            let _ = self.reject_for_body_disallowed(body, source);
        }
        let baseline = consuming.then(|| self.scopes[block_scope].bindings.clone());
        let owned_record_item = element.as_ref().is_some_and(|element| {
            crate::source_verify::declared_type::owned_leaf_collection::runtime_element(
                self.types, element,
            )
        });
        let _ = self.reject_iterator_body(
            body,
            (consuming && (element == Some(Type::Bytes) || owned_record_item)).then_some(item),
        );
        let item_inserted = !self.scopes[block_scope].bindings.contains_key(item);
        if !item_inserted {
            self.diagnostics.push(error(
                self.program,
                "SPX-T209",
                format!("loop item `{item}` shadows an existing value"),
                item_span,
            ));
        }
        if item_inserted {
            if let Some(element) = element {
                self.scopes[block_scope].bindings.insert(
                    item.to_owned(),
                    Binding { contract_local: false, traversal_row: None,
                        mode: if consuming
                            && (element == Type::Bytes
                                || crate::source_verify::declared_type::owned_leaf_collection::runtime_element(
                                        self.types,
                                        &element,
                                    ))
                        {
                            ParamMode::Own
                        } else {
                            ParamMode::Value
                        },
                        ty: element,
                        availability: Availability::Available,
                        moved_places: HashMap::new(),
                        definitely_partial: HashSet::new(),
                        native_unit_discard: false,
                        mutable: false,
                        active_loans: BTreeSet::new(),
                        borrow_origin: None,
                    },
                );
            }
        }
        if borrowing && item_inserted {
            if let Some(source) = source {
                let selected_index = match &statements[index] {
                    Statement::ForBorrow {
                        index: Some(selected),
                        ..
                    } => Some(selected.name.as_str()),
                    _ => None,
                };
                match crate::source_verify::record_traversal::body_binding_conflict(
                    body,
                    source,
                    item,
                    selected_index,
                ) {
                    Ok(Some(span)) => {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T284",
                            "record traversal cannot shadow its carrier, row or index binding",
                            span,
                        ));
                    }
                    Ok(None) => {}
                    Err(()) => self.diagnostics.push(error(
                        self.program,
                        "SPX-T284",
                        "record traversal binding scan exceeds its source scratch, depth or work budget",
                        body.span,
                    )),
                }

                if let Some(binding) = self.scopes[block_scope].bindings.get_mut(item) {
                    binding.mode = ParamMode::Borrow;
                    binding.traversal_row =
                        Some(Box::new(crate::source_verify::record_traversal::Row {
                            root: source.to_owned(),
                            element: binding.ty.clone(),
                            index_inserted: false,
                            freeze: crate::source_verify::binding::SourceLoanId {
                                borrower: item.to_owned(),
                                start: values.span.start,
                                end: body.span.end,
                            },
                        }));
                }
            }
            if let Some(row) = self.scopes[block_scope]
                .bindings
                .get(item)
                .and_then(|binding| binding.traversal_row.as_deref())
                .cloned()
            {
                if let Some(owner) = self.scopes[block_scope].bindings.get_mut(&row.root) {
                    owner
                        .active_loans
                        .insert(crate::source_verify::binding::SourceLoan {
                            id: row.freeze,
                            projections: Vec::new(),
                        });
                }
            }
            if let Statement::ForBorrow {
                index: Some(selected),
                ..
            } = &statements[index]
            {
                if selected.name == item
                    || self.scopes[block_scope]
                        .bindings
                        .contains_key(&selected.name)
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T209",
                        "record traversal index must be a fresh distinct binding",
                        selected.span,
                    ));
                } else {
                    self.scopes[block_scope].bindings.insert(
                        selected.name.clone(),
                        Binding {
                            contract_local: false,
                            ty: Type::Usize,
                            mode: ParamMode::Value,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: false,
                            mutable: false,
                            active_loans: BTreeSet::new(),
                            borrow_origin: None,
                            traversal_row: None,
                        },
                    );
                    if let Some(row) = self.scopes[block_scope]
                        .bindings
                        .get_mut(item)
                        .and_then(|binding| binding.traversal_row.as_deref_mut())
                    {
                        row.index_inserted = true;
                    }
                }
            }
        }
        let byte_source = actual
            .as_ref()
            .is_some_and(|actual| actual.ty == Type::SliceU8)
            && !consuming
            && !borrowing;
        if let (true, Some(source)) = (byte_source && item_inserted, source) {
            crate::source_verify::byte_traversal::freeze(
                &mut self.scopes[block_scope].bindings,
                source,
                &crate::source_verify::byte_traversal::freeze_id(item, values.span, body.span),
            );
        }
        self.frames
            .push(crate::source_verify::scope::VerifierFrame::ResumeForBody {
                expression,
                statements,
                tail,
                parent_scope,
                block_scope,
                index,
                outer_names,
                item,
                item_inserted,
                source,
                baseline,
            });
        self.loop_depth += 1;
        if item_inserted && consuming && owned_record_item {
            self.owned_iterator_items.push(item.to_owned());
        }
        self.frames
            .push(crate::source_verify::scope::VerifierFrame::Enter {
                expression: body,
                scope: block_scope,
            });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_for_body(
        &mut self,
        expression: &'p Expr,
        statements: &'p [Statement],
        tail: &'p Expr,
        parent_scope: usize,
        block_scope: usize,
        index: usize,
        outer_names: Vec<String>,
        item: &str,
        item_inserted: bool,
        source: Option<&str>,
        baseline: Option<HashMap<String, Binding>>,
    ) -> Result<(), Diagnostic> {
        let _ = self.values.pop();
        self.loop_depth = self.loop_depth.saturating_sub(1);
        if item_inserted
            && self
                .owned_iterator_items
                .last()
                .is_some_and(|active| active == item)
        {
            self.owned_iterator_items.pop();
        }
        if let Some(row) = self.scopes[block_scope]
            .bindings
            .get(item)
            .and_then(|binding| binding.traversal_row.as_deref())
            .cloned()
        {
            if let Some(owner) = self.scopes[block_scope].bindings.get_mut(&row.root) {
                owner.active_loans.retain(|loan| loan.id != row.freeze);
            }
        }
        if let Statement::For { values, body, .. } = &statements[index] {
            crate::source_verify::byte_traversal::release(
                &mut self.scopes[block_scope].bindings,
                &crate::source_verify::byte_traversal::freeze_id(item, values.span, body.span),
            );
        }
        let index_inserted = self.scopes[block_scope]
            .bindings
            .get(item)
            .and_then(|binding| binding.traversal_row.as_deref())
            .is_some_and(|row| row.index_inserted);
        if item_inserted {
            self.scopes[block_scope].bindings.remove(item);
        }
        if let Statement::ForBorrow {
            index: Some(selected),
            ..
        } = &statements[index]
        {
            // Remove only a successfully inserted index. A hostile collision
            // leaves the authoritative outer binding in place.
            if index_inserted {
                self.scopes[block_scope].bindings.remove(&selected.name);
            }
        }
        if let Some(baseline) = baseline {
            if statements[index]
                .child(1)
                .is_some_and(crate::ast::returns_only)
            {
                for (name, binding) in &baseline {
                    self.scopes[block_scope]
                        .bindings
                        .insert(name.clone(), binding.clone());
                }
            }

            let mut names = baseline.keys().collect::<Vec<_>>();
            names.sort();
            for name in names {
                let before = &baseline[name];
                if self.scopes[block_scope]
                    .bindings
                    .get(name)
                    .is_none_or(|after| {
                        after.availability != before.availability
                            || after.moved_places != before.moved_places
                            || after.definitely_partial != before.definitely_partial
                    })
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T252",
                        format!("ownership of `{name}` changes inside a for own loop"),
                        statements[index]
                            .child(1)
                            .map_or(Span::default(), |body| body.span),
                    ));
                }
            }
        }
        if let Some(source) = source {
            let changed = self.scopes[block_scope]
                .bindings
                .get(source)
                .is_none_or(|after| {
                    after.availability != Availability::Available
                        || !after.moved_places.is_empty()
                        || !after.definitely_partial.is_empty()
                });
            if changed {
                self.diagnostics.push(error(
                    self.program, "SPX-T284",
                    format!("for traversal source `{source}` cannot be consumed or mutated in the loop body"),
                    statements[index].child(1).map_or(Span::default(), |body| body.span),
                ));
            }
        }
        self.advance_block_statement(
            expression,
            statements,
            tail,
            parent_scope,
            block_scope,
            index,
            outer_names,
        );
        Ok(())
    }

    pub(super) fn frame_resume_block_tail(
        &mut self,
        parent_scope: usize,
        block_scope: usize,
        outer_names: Vec<String>,
    ) -> Result<(), Diagnostic> {
        if block_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "block verifier scope is not the active child",
            ));
        }
        let actual = self.values.pop().unwrap_or(None);
        let block_bindings = self
            .scopes
            .pop()
            .expect("active block scope index checked above")
            .bindings;
        merge_moved(
            &mut self.scopes[parent_scope].bindings,
            &block_bindings,
            &outer_names,
        );
        self.values.push(actual);
        Ok(())
    }
}

//! Call, method call, `?`, and projection frames: argument resumption and
//! the ownership transfers at each call boundary.

use crate::ast::{Expr, Function, ImportResult, ParamMode, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::IterativeVerifier;
use crate::source_verify::arguments::{
    check_argument_ownership, release_borrowed_bytes_call_loans,
};
use crate::source_verify::binding::{Availability, CheckedValue, SourceLoanId};
use crate::source_verify::declared_type::{ordinary_option_argument, ordinary_result_arguments};
use crate::source_verify::diagnostics::{error, reject_native_unit_value};
use crate::source_verify::hints;
use crate::source_verify::loans::mark_value_sources_moved;
use crate::source_verify::private_names::type_name;
use crate::source_verify::scope::{VerifierCallTarget, VerifierFrame, VerifierFunctionSignature};
use crate::source_verify::type_table::{effective_record_fields, resolve_class_method};

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_call_argument(
        &mut self,
        expression: &'p Expr,
        name: &'p str,
        args: &'p [Expr],
        scope: usize,
        index: usize,
        target: VerifierCallTarget<'p>,
        borrowed_bytes_loans: Vec<(String, SourceLoanId)>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let argument = &args[index];
        match &target {
            VerifierCallTarget::LiteralFormat => {
                if index > 0 {
                    if let Some(actual) = &actual {
                        reject_native_unit_value(self.program, argument, actual, self.diagnostics);
                        if !actual.native_unit
                            && !crate::literal_format::accepts_ast_type(&actual.ty)
                            && !self.recovery.explains_acceptance(
                                argument,
                                crate::literal_format::accepts_ast_type,
                            )
                        {
                            self.diagnostics.push(error(self.program, "SPX-T205", format!("string_format value {} must be i64, u8, usize, bool, or own string", index - 1), argument.span));
                        }
                        let parameter = crate::ast::Param {
                            name: format!("value{}", index - 1),
                            mode: if actual.ty == Type::String {
                                ParamMode::Own
                            } else {
                                ParamMode::Value
                            },
                            ty: actual.ty.clone(),
                            span: argument.span,
                        };
                        check_argument_ownership(
                            self.program,
                            self.current,
                            name,
                            argument,
                            &parameter,
                            Some(actual),
                            &mut self.scopes[scope].bindings,
                            self.types,
                            self.allow_moves,
                            false,
                            false,
                            self.diagnostics,
                        );
                    }
                }
            }
            VerifierCallTarget::Native(import) => {
                if let (Some(actual), Some(parameter)) = (actual.as_ref(), import.params.get(index))
                {
                    reject_native_unit_value(self.program, argument, actual, self.diagnostics);
                    check_argument_ownership(
                        self.program,
                        self.current,
                        name,
                        argument,
                        parameter,
                        Some(actual),
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.allow_moves,
                        false,
                        false,
                        self.diagnostics,
                    );
                    if !actual.native_unit
                        && (actual.ty != parameter.ty
                            || (actual.mode != parameter.mode
                                && !(parameter.mode == ParamMode::Borrow
                                    && actual.mode == ParamMode::Own
                                    && matches!(&argument.kind, crate::ast::ExprKind::Var(_)))))
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-B107",
                        "Native Rust Interop declaration set is unsupported: scalar value signature required",
                            argument.span,
                        ));
                    }
                }
            }
            VerifierCallTarget::Ordinary(specialized) => {
                if let Some(param) = specialized
                    .as_ref()
                    .and_then(|target| target.params().get(index))
                {
                    if let Some(actual) = &actual {
                        reject_native_unit_value(self.program, argument, actual, self.diagnostics);
                    }
                    if let Some(actual) = actual.as_ref().filter(|actual| {
                        !actual.native_unit
                            && actual.ty != param.ty
                            && !self.recovery.explains(argument, &param.ty)
                    }) {
                        self.diagnostics.push(hints::with_optional_help(
                            error(
                                self.program,
                                "SPX-T205",
                                format!(
                                    "argument `{}` to `{name}` expects {}, received {}",
                                    param.name,
                                    type_name(self.program, self.types, &param.ty),
                                    type_name(self.program, self.types, &actual.ty)
                                ),
                                argument.span,
                            ),
                            hints::argument_view_help(name, &param.ty, &actual.ty),
                        ));
                    }
                    check_argument_ownership(
                        self.program,
                        self.current,
                        name,
                        argument,
                        param,
                        actual.as_ref(),
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.allow_moves,
                        specialized
                            .as_ref()
                            .is_some_and(VerifierFunctionSignature::implicit_unique_ownership),
                        matches!(
                            specialized.as_ref(),
                            Some(VerifierFunctionSignature::Borrowed(function))
                                if function.type_parameters.is_empty()
                        ),
                        self.diagnostics,
                    );
                }
            }
            VerifierCallTarget::Byte(op) => {
                if let Some(actual) = &actual {
                    reject_native_unit_value(self.program, argument, actual, self.diagnostics);
                    if !actual.native_unit
                        && !op.accepts_ast(index, &actual.ty)
                        && !self.recovery.explains_acceptance(argument, |declared| {
                            op.accepts_ast(index, declared)
                        })
                    {
                        self.diagnostics.push(hints::with_optional_help(
                            error(
                                self.program,
                                "SPX-T263",
                                format!(
                                    "byte operation `{name}` argument {index} has the wrong type"
                                ),
                                argument.span,
                            ),
                            hints::view_argument_help(name, &actual.ty),
                        ));
                    }
                }
            }
            VerifierCallTarget::HostIo(op) => {
                if let Some(actual) = &actual {
                    reject_native_unit_value(self.program, argument, actual, self.diagnostics);
                    if !actual.native_unit
                        && !op.accepts_ast(index, &actual.ty)
                        && !self.recovery.explains_acceptance(argument, |declared| {
                            op.accepts_ast(index, declared)
                        })
                    {
                        self.diagnostics.push(hints::with_optional_help(
                            error(
                                self.program,
                                "SPX-T269",
                                format!(
                                    "host I/O operation `{name}` argument {index} has the wrong type"
                                ),
                                argument.span,
                            ),
                            hints::view_argument_help(name, &actual.ty),
                        ));
                    }
                }
            }
            VerifierCallTarget::CommandIo(op) => {
                if crate::stdin_stream_ops::is_host(*op) {
                    if let Some(parameter) = crate::command_io_ops::ast_params(*op).get(index) {
                        check_argument_ownership(
                            self.program,
                            self.current,
                            name,
                            argument,
                            parameter,
                            actual.as_ref(),
                            &mut self.scopes[scope].bindings,
                            self.types,
                            self.allow_moves,
                            false,
                            false,
                            self.diagnostics,
                        );
                    }
                }
                if let Some(actual) = &actual {
                    reject_native_unit_value(self.program, argument, actual, self.diagnostics);
                    if !actual.native_unit
                        && !crate::command_io_ops::accepts_ast(*op, index, &actual.ty)
                        && !self.recovery.explains_acceptance(argument, |declared| {
                            crate::command_io_ops::accepts_ast(*op, index, declared)
                        })
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T270",
                            format!(
                                "command I/O operation `{name}` argument {index} has the wrong type"
                            ),
                            argument.span,
                        ));
                    }
                }
            }
        }
        let next = index + 1;
        if let Some(argument) = args.get(next) {
            self.frames.push(VerifierFrame::ResumeCallArgument {
                expression,
                name,
                args,
                scope,
                index: next,
                target,
                borrowed_bytes_loans,
            });
            self.frames.push(VerifierFrame::Enter {
                expression: argument,
                scope,
            });
        } else {
            release_borrowed_bytes_call_loans(
                &mut self.scopes[scope].bindings,
                &borrowed_bytes_loans,
            );
            let output = match target {
                VerifierCallTarget::LiteralFormat => {
                    Some(CheckedValue::returned(Type::String, true))
                }
                VerifierCallTarget::Native(import) => {
                    let mut value = CheckedValue::returned(
                        import.result.value_type(),
                        import.result.is_owned(),
                    );
                    value.native_unit = import.result == ImportResult::Unit;
                    if import.result.is_borrowed() {
                        value.mode = ParamMode::Borrow;
                    }
                    Some(value)
                }
                VerifierCallTarget::Byte(op) => {
                    // A private partition returns a nominal owned Vec;
                    // scalar/view byte results remain non-owning.
                    let ty = op.ast_return_type();
                    let owns = self.types.needs_drop(&ty);
                    Some(CheckedValue::returned(ty, owns))
                }
                VerifierCallTarget::HostIo(op) => {
                    Some(CheckedValue::returned(op.ast_return_type(), false))
                }
                VerifierCallTarget::CommandIo(op) => Some(CheckedValue {
                    ty: crate::command_io_ops::ast_return_type(op),
                    mode: match op {
                        crate::hir::ResolvedHostCommandOperation::ArgUtf8 => ParamMode::Borrow,
                        crate::hir::ResolvedHostCommandOperation::StdinRead => ParamMode::Own,
                        crate::hir::ResolvedHostCommandOperation::ArgsLen
                        | crate::hir::ResolvedHostCommandOperation::StderrWrite
                        | crate::hir::ResolvedHostCommandOperation::StdoutAppend
                        | crate::hir::ResolvedHostCommandOperation::StderrAppend => {
                            ParamMode::Value
                        }
                        operation => match crate::command_io_ops::result_ownership(operation) {
                            crate::hir::OwnershipMode::Own => ParamMode::Own,
                            crate::hir::OwnershipMode::Borrow => ParamMode::Borrow,
                            _ => ParamMode::Value,
                        },
                    },
                    native_unit: false,
                }),
                VerifierCallTarget::Ordinary(Some(target)) => Some(CheckedValue::returned(
                    target.return_type().clone(),
                    self.types.needs_drop(target.return_type()),
                )),
                VerifierCallTarget::Ordinary(None) => None,
            };
            let output = output.map(|mut value| {
                if (name == crate::vec_field::NAME || name == crate::vec_ops::string_slot::NAME)
                    && matches!(value.ty, Type::Str | Type::SliceU8)
                {
                    value.mode = ParamMode::Borrow;
                }
                value
            });
            self.values.push(output);
        }
        Ok(())
    }

    pub(super) fn frame_resume_method_receiver(
        &mut self,
        expression: &'p Expr,
        receiver: &'p Expr,
        method: &'p str,
        args: &'p [Expr],
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let Some(receiver_value) = actual else {
            self.values.push(None);
            return Ok(());
        };
        let Type::Named {
            name: class_name,
            arguments: class_arguments,
        } = &receiver_value.ty
        else {
            self.diagnostics.push(hints::with_optional_help(
                error(
                    self.program,
                    "SPX-T203",
                    format!(
                        "method `{method}` requires a class receiver, found `{}`",
                        receiver_value.ty
                    ),
                    receiver.span,
                ),
                hints::method_receiver_help(&receiver_value.ty, method),
            ));
            self.values.push(None);
            return Ok(());
        };
        if !class_arguments.is_empty() {
            self.diagnostics.push(error(
                self.program,
                "SPX-T203",
                format!(
                    "method `{method}` on generic class `{class_name}` is not supported in this slice"
                ),
                expression.span,
            ));
            self.values.push(None);
            return Ok(());
        }
        let declaration = self.types.declaration(class_name);
        let _ = declaration;
        // Class Inheritance v1: resolution walks the receiver's
        // ancestor chain nearest-first; an inherited method's
        // declared class owns the expected `self` type.
        let Some((holder_name, method_fn)) = resolve_class_method(self.types, class_name, method)
        else {
            self.diagnostics.push(hints::with_optional_help(
                error(
                    self.program,
                    "SPX-T203",
                    format!("unknown method `{method}` on `{class_name}`"),
                    expression.span,
                ),
                hints::non_class_method_help(self.types, class_name),
            ));
            self.values.push(None);
            return Ok(());
        };
        let Some(self_param) = method_fn.params.first() else {
            self.diagnostics.push(error(
                self.program,
                "SPX-T205",
                format!("method `{method}` on `{class_name}` has no `self` parameter"),
                method_fn.span,
            ));
            self.values.push(None);
            return Ok(());
        };
        let expected_self = Type::Named {
            name: holder_name.to_owned(),
            arguments: Vec::new(),
        };
        if self_param.mode != ParamMode::Value || self_param.ty != expected_self {
            self.diagnostics.push(error(
                self.program,
                "SPX-T205",
                format!(
                    "method `{method}` expects a value-mode `self: {holder_name}` receiver, found `{}`",
                    self_param.ty
                ),
                self_param.span,
            ));
            self.values.push(None);
            return Ok(());
        }
        if method_fn.params.len() - 1 != args.len() {
            self.diagnostics.push(error(
                self.program,
                "SPX-T204",
                format!(
                    "`{}.{}` expects {} arguments, received {}",
                    class_name,
                    method,
                    method_fn.params.len() - 1,
                    args.len()
                ),
                expression.span,
            ));
            self.values.push(None);
            return Ok(());
        }
        check_argument_ownership(
            self.program,
            self.current,
            method_fn.name.as_str(),
            receiver,
            self_param,
            Some(&receiver_value),
            &mut self.scopes[scope].bindings,
            self.types,
            self.allow_moves,
            true,
            false,
            self.diagnostics,
        );
        if args.is_empty() {
            self.values.push(Some(CheckedValue::returned(
                method_fn.return_type.clone(),
                self.types.needs_drop(&method_fn.return_type),
            )));
            return Ok(());
        }
        self.frames.push(VerifierFrame::ResumeMethodArgument {
            expression,
            method: method_fn,
            args,
            scope,
            index: 0,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: &args[0],
            scope,
        });
        Ok(())
    }

    pub(super) fn frame_resume_method_argument(
        &mut self,
        expression: &'p Expr,
        method: &'p Function,
        args: &'p [Expr],
        scope: usize,
        index: usize,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let argument = &args[index];
        if let Some(param) = method.params.get(index + 1) {
            if let Some(actual) = &actual {
                reject_native_unit_value(self.program, argument, actual, self.diagnostics);
            }
            if actual.as_ref().is_some_and(|actual| {
                !actual.native_unit
                    && actual.ty != param.ty
                    && !self.recovery.explains(argument, &param.ty)
            }) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T205",
                    format!(
                        "argument `{}` to `{}` expects {}, received {}",
                        param.name,
                        method.name,
                        param.ty,
                        actual.as_ref().expect("type checked above").ty
                    ),
                    argument.span,
                ));
            }
            check_argument_ownership(
                self.program,
                self.current,
                method.name.as_str(),
                argument,
                param,
                actual.as_ref(),
                &mut self.scopes[scope].bindings,
                self.types,
                self.allow_moves,
                true,
                false,
                self.diagnostics,
            );
        }
        let next = index + 1;
        if let Some(argument) = args.get(next) {
            self.frames.push(VerifierFrame::ResumeMethodArgument {
                expression,
                method,
                args,
                scope,
                index: next,
            });
            self.frames.push(VerifierFrame::Enter {
                expression: argument,
                scope,
            });
        } else {
            self.values.push(Some(CheckedValue::returned(
                method.return_type.clone(),
                self.types.needs_drop(&method.return_type),
            )));
        }
        Ok(())
    }

    pub(super) fn frame_resume_try(
        &mut self,
        expression: &'p Expr,
        operand: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let Some(operand_value) = self.values.pop().flatten() else {
            self.values.push(None);
            return Ok(());
        };
        reject_native_unit_value(self.program, operand, &operand_value, self.diagnostics);
        if !self.allow_moves {
            self.diagnostics.push(error(
                self.program,
                "SPX-T218",
                "`?` is only valid in an executable function body",
                expression.span,
            ));
        }
        let exact_owned_result = crate::source_verify::declared_type::generic_result::concrete_try(
            &operand_value.ty,
            &self.current.return_type,
        );
        if exact_owned_result && self.allow_moves {
            mark_value_sources_moved(
                self.program,
                operand,
                &mut self.scopes[scope].bindings,
                self.types,
                self.diagnostics,
            );
        }
        if self.scopes[scope].bindings.values().any(|binding| {
            binding.availability != Availability::Moved && self.types.needs_drop(&binding.ty)
        }) {
            self.diagnostics.push(error(
                self.program,
                "SPX-T218",
                "`?` with a live resource binding is not supported yet",
                expression.span,
            ));
        }
        if let Some((ok, error_ty)) = ordinary_result_arguments(&operand_value.ty) {
            let Some((_residual_ok_ty, residual_error_ty)) =
                ordinary_result_arguments(&self.current.return_type)
            else {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T218",
                    format!(
                        "function `{}` must return the ordinary compiler-owned Result to propagate a Result with `?`",
                        self.current.name
                    ),
                    expression.span,
                ).with_help(crate::source_verify::hints::TRY_RESULT_RETURN_HELP));
                self.values.push(Some(CheckedValue::value(ok.clone())));
                return Ok(());
            };
            if error_ty != residual_error_ty {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T219",
                    format!("`?` cannot propagate error type {error_ty} into Result error type {residual_error_ty}"),
                    expression.span,
                ));
            }
            let exact_owned = exact_owned_result;
            if !exact_owned
                && (!matches!(ok, Type::I64 | Type::Bool)
                    || !matches!(error_ty, Type::I64 | Type::Bool)
                    || !matches!(residual_error_ty, Type::I64 | Type::Bool))
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T218",
                    "Result `?` accepts only direct `i64` or `bool` success and error payloads",
                    expression.span,
                ));
            }
            self.values.push(Some(CheckedValue::value(ok.clone())));
            return Ok(());
        }
        if let Some(some) = ordinary_option_argument(&operand_value.ty) {
            let outer = ordinary_option_argument(&self.current.return_type);
            if outer.is_none() {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T218",
                    format!("function `{}` must return the ordinary compiler-owned Option to propagate an Option with `?`", self.current.name),
                    expression.span,
                ));
            } else if !matches!(some, Type::I64 | Type::Bool)
                || outer.is_some_and(|value| !matches!(value, Type::I64 | Type::Bool))
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T218",
                    "Option `?` accepts only direct `i64` or `bool` source and enclosing payloads",
                    expression.span,
                ));
            }
            self.values.push(Some(CheckedValue::value(some.clone())));
            return Ok(());
        }
        self.diagnostics.push(error(
            self.program,
            "SPX-T218",
            format!(
                "`?` operand must be an ordinary compiler-owned Result or Option, received {}",
                type_name(self.program, self.types, &operand_value.ty)
            ),
            expression.span,
        ));
        self.values.push(None);
        Ok(())
    }

    /// Resumable Effects v1 (issue #204): the request's own verified value
    /// is discarded (its type was already checked against the declared
    /// request type by `hir::resolve_yield`); the whole `yield` expression
    /// verifies as the enclosing function's declared response type. Falls
    /// back to `None` (unverified) rather than a wrong or asserted type if
    /// this function turns out not to declare `yields` at all -- a case
    /// `parser::yields`/`hir::resolve_yield` already refuse, so this is
    /// defensive only.
    pub(super) fn frame_resume_yield(
        &mut self,
        _expression: &'p Expr,
        _request: &'p Expr,
    ) -> Result<(), Diagnostic> {
        self.values.pop();
        let value = self
            .current
            .yields
            .as_ref()
            .map(|yields| CheckedValue::value(yields.response_type.clone()));
        self.values.push(value);
        Ok(())
    }

    pub(super) fn frame_resume_project(
        &mut self,
        expression: &'p Expr,
        base: &'p Expr,
        field: &'p str,
    ) -> Result<(), Diagnostic> {
        let Some(base_value) = self.values.pop().flatten() else {
            self.values.push(None);
            return Ok(());
        };
        reject_native_unit_value(self.program, base, &base_value, self.diagnostics);
        if self.loop_depth != 0
            && !crate::source_verify::declared_type::owned_leaf_collection::copy_or_leaf_admitted(
                self.types,
                &base_value.ty,
            )
            && !crate::source_verify::declared_type::collection_record::admitted(
                &base_value.ty,
                self.types,
            )
        {
            self.diagnostics.push(error(
                self.program,
                "SPX-T252",
                "record field projection is not yet admitted in while bodies",
                expression.span,
            ));
        }
        let Some(fields) = effective_record_fields(self.types, &base_value.ty) else {
            self.diagnostics.push(error(
                self.program,
                "SPX-T214",
                format!("cannot project field `{field}` from `{}`", base_value.ty),
                expression.span,
            ));
            self.values.push(None);
            return Ok(());
        };
        let Some(declared) = fields.iter().find(|candidate| candidate.name == field) else {
            self.diagnostics.push(error(
                self.program,
                "SPX-T214",
                format!("record `{}` has no field `{field}`", base_value.ty),
                expression.span,
            ));
            self.values.push(None);
            return Ok(());
        };
        let projected = self
            .types
            .record_field_type(&base_value.ty, declared)
            .unwrap_or_else(|| declared.ty.clone());
        let mode = if self.types.needs_drop(&projected) {
            base_value.mode
        } else {
            ParamMode::Value
        };
        self.values.push(Some(CheckedValue {
            ty: projected,
            mode,
            native_unit: false,
        }));
        Ok(())
    }
}

//! The `Enter` frame: the first visit to an expression, which either
//! produces a value directly or schedules the frames its operands need.

use crate::ast::{Expr, ExprKind, ImportResult, ParamMode, Statement, Type, TypeDeclarationKind};
use crate::diagnostic::Diagnostic;
use crate::source_verify::IterativeVerifier;
use crate::source_verify::arguments::{
    activate_borrowed_bytes_call_loans, source_byte_view_place_is_admitted,
};
use crate::source_verify::binding::{Availability, CheckedValue};
use crate::source_verify::declared_type::{
    check_declared_type, function_value_signature, generic_function_arguments_are_admitted,
    generic_function_arguments_are_forwarded, validation_specialize_signature,
};
use crate::source_verify::diagnostics::{error, source_identifier};
use crate::source_verify::hints;
use crate::source_verify::place::{
    check_source_place_availability, overlapping_place_state, source_place,
};
use crate::source_verify::scope::{
    VerifierCallTarget, VerifierFrame, VerifierFunctionSignature, VerifierScope,
};
use crate::source_verify::type_table::effective_record_fields;
use std::collections::HashSet;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn frame_enter(
        &mut self,
        expression: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        #[cfg(test)]
        if self.recovery_legacy {
            return self.recovery_old_frame_enter(expression, scope);
        }

        self.recovery.begin(expression);
        match &expression.kind {
            ExprKind::VecConstructor { .. } => {
                let hygienic = *self.constructor_hygiene.get_or_insert_with(|| {
                    crate::ast::expression_statement::projection_roots(
                        self.current
                            .requires
                            .iter()
                            .chain(std::iter::once(&self.current.body))
                            .chain(&self.current.ensures),
                        self.current
                            .params
                            .iter()
                            .map(|param| param.name.as_str())
                            .chain(
                                self.current
                                    .type_parameters
                                    .iter()
                                    .map(|param| param.name.as_str()),
                            ),
                        crate::bounded_output::reserve_active_required,
                    )
                });
                if !hygienic {
                    return Err(error(
                        self.program,
                        "SPX-T318",
                        "Vec constructor generated owner names are not hygienic",
                        expression.span,
                    ));
                }
                let expansion = crate::ast::vec_constructor::inspect(expression)
                    .map_err(|message| error(self.program, "SPX-T318", message, expression.span))?;
                self.frames.push(VerifierFrame::Enter {
                    expression: expansion.value,
                    scope,
                });
            }
            ExprKind::LexicalExit { kind, value } => {
                if let Some(operand) = value {
                    self.frames.push(VerifierFrame::ResumeLexicalReturn {
                        expression,
                        operand,
                        scope,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: operand,
                        scope,
                    });
                } else if *kind != crate::ast::LexicalExitKind::Return {
                    self.values.push(Some(CheckedValue::value(Type::Never)));
                } else {
                    return Err(error(
                        self.program,
                        "SPX-T312",
                        "return requires an operand",
                        expression.span,
                    ));
                }
            }
            ExprKind::Closure { .. } => self.enter_closure(expression, scope)?,
            ExprKind::Int(_) => self.values.push(Some(CheckedValue::value(Type::I64))),
            ExprKind::Int32(_) => self.values.push(Some(CheckedValue::value(Type::I32))),
            ExprKind::Char(_) => self.values.push(Some(CheckedValue::value(Type::Char))),
            ExprKind::Uint8(_) => self.values.push(Some(CheckedValue::value(Type::U8))),
            ExprKind::Usize(_) => self.values.push(Some(CheckedValue::value(Type::Usize))),
            ExprKind::ArrayU8(values) => self.values.push(Some(CheckedValue::value(
                Type::ArrayU8(values.len() as u32),
            ))),
            ExprKind::RepeatArrayU8 { count, .. } => self
                .values
                .push(Some(CheckedValue::value(Type::ArrayU8(*count)))),
            ExprKind::Float32(_) => self.values.push(Some(CheckedValue::value(Type::F32))),
            ExprKind::Float64(_) => self.values.push(Some(CheckedValue::value(Type::F64))),
            ExprKind::Bool(_) => self.values.push(Some(CheckedValue::value(Type::Bool))),
            ExprKind::String(_) => self.values.push(Some(CheckedValue::value(Type::String))),
            ExprKind::BorrowedUtf8Literal(text) => {
                self.values
                    .push(Some(crate::source_verify::static_text::checked(
                        self.program,
                        expression.span,
                        text,
                    )?))
            }
            ExprKind::Var(name) if name == "result" => {
                let value = self
                    .result_type
                    .map(|ty| CheckedValue::returned(ty.clone(), self.types.needs_drop(ty)));
                if value.is_none() {
                    self.diagnostics.push(
                        error(
                            self.program,
                            "SPX-T201",
                            "`result` is only available in postconditions",
                            expression.span,
                        )
                        .with_help(hints::RESULT_NAME_HELP),
                    );
                }
                self.values.push(value);
            }
            ExprKind::Var(name) => {
                if self.scopes[scope]
                    .bindings
                    .get(name)
                    .is_some_and(|binding| binding.traversal_row.is_some())
                    && !self
                        .row_loan_sites
                        .contains(&(expression.span.start, expression.span.end))
                {
                    return Err(error(
                        self.program,
                        "SPX-T284",
                        "record traversal row cannot escape or materialize aggregate storage; select a field",
                        expression.span,
                    ));
                }
                let value = self.scopes[scope].bindings.get(name).map(|binding| {
                    crate::source_verify::owning_closure::reject_escaping_read(
                        self.program,
                        name,
                        &binding.ty,
                        expression.span,
                        self.diagnostics,
                    );
                    match binding.availability {
                        Availability::Moved => self.diagnostics.push(
                            error(
                                self.program,
                                "SPX-O101",
                                format!("use of resource `{name}` after ownership was moved"),
                                expression.span,
                            )
                            .with_help(crate::source_verify::hints::moved_resource_help(
                                &binding.ty,
                                name,
                            )),
                        ),
                        Availability::MaybeMoved => self.diagnostics.push(
                            error(
                                self.program,
                                "SPX-O107",
                                format!("resource `{name}` may have been moved on another control-flow path"),
                                expression.span,
                            )
                            .with_help(crate::source_verify::hints::moved_resource_help(
                                &binding.ty,
                                name,
                            )),
                        ),
                        Availability::Available => match overlapping_place_state(binding, &[]) {
                            Availability::Moved => self.diagnostics.push(
                                error(self.program, "SPX-O109", format!("use of partially moved place `{name}`"), expression.span)
                                    .with_help("use an available sibling field or avoid moving this place earlier"),
                            ),
                            Availability::MaybeMoved => self.diagnostics.push(
                                error(self.program, "SPX-O110", format!("place `{name}` may have been moved on another control-flow path"), expression.span)
                                    .with_help("move the field on every path or keep it borrowed"),
                            ),
                            Availability::Available => {}
                        },
                    }
                    if binding.native_unit_discard {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-B107",
                            "Native Rust Interop declaration set is unsupported: scalar value signature required",
                            expression.span,
                        ));
                    }
                    CheckedValue { ty: binding.ty.clone(), mode: binding.mode, native_unit: binding.native_unit_discard }
                });
                let value = value.or_else(|| {
                    self.functions
                        .get(name.as_str())
                        .and_then(|function| function_value_signature(function))
                        .map(CheckedValue::value)
                });
                if value.is_none() && !self.recovery.reads_refused(scope, name) {
                    self.diagnostics.push(hints::with_optional_help(
                        error(
                            self.program,
                            "SPX-T202",
                            format!("unknown value `{name}` in `{}`", self.current.name),
                            expression.span,
                        ),
                        hints::variant_shorthand_help(name).map(str::to_owned),
                    ));
                }
                // Preserve every real binding/ownership check above before
                // attaching a separate expected-type refusal view to this read.
                let refused = value.is_some() && self.recovery.reads_value(scope, name, expression);
                self.values.push(if refused { None } else { value });
            }
            ExprKind::Unary { op, value } => {
                self.frames.push(VerifierFrame::ResumeUnary {
                    expression,
                    operand: value,
                    op: *op,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: value,
                    scope,
                });
            }
            ExprKind::Binary { op, left, right } => {
                self.frames.push(VerifierFrame::ResumeBinaryLeft {
                    expression,
                    op: *op,
                    right,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: left,
                    scope,
                });
            }
            ExprKind::Call {
                name,
                type_arguments,
                args,
            } => {
                let args: &[Expr] = if name == crate::vec_ops::sort_keys::NAME {
                    if !self.current.type_parameters.is_empty()
                        || crate::source_verify::sort_keys::descriptor(
                            self.types,
                            type_arguments,
                            args,
                        )
                        .is_none()
                    {
                        self.diagnostics.push(error(self.program,"SPX-T311","vec_sort_by requires an explicit monomorphic record and 1..8 unique literal field:asc/field:desc keys",expression.span));
                        self.values.push(None);
                        return Ok(());
                    }
                    &args[..1]
                } else if name == crate::vec_ops::field_unique::NAME {
                    if !self.current.type_parameters.is_empty()
                        || crate::source_verify::field_unique::descriptor(
                            self.types,
                            type_arguments,
                            args,
                            &self.scopes[scope].bindings,
                        )
                        .is_none()
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T319",
                            crate::vec_ops::field_unique::SHAPE,
                            expression.span,
                        ));
                        self.values.push(None);
                        return Ok(());
                    }
                    &args[..1]
                } else {
                    args
                };
                if let Some(result) = crate::source_verify::owning_closure::check_call(
                    self.program,
                    name,
                    type_arguments,
                    args,
                    expression.span,
                    self.allow_moves,
                    &mut self.scopes[scope].bindings,
                    self.types,
                    self.diagnostics,
                ) {
                    self.values.push(result);
                    return Ok(());
                }
                let native = self
                    .program
                    .interfaces()
                    .iter()
                    .flat_map(|interface| &interface.imports)
                    .find(|import| import.native_rust && import.name == *name);
                let callable_binding = self.scopes[scope].bindings.get(name).map(|binding| {
                    crate::source_verify::mutable_closure::invocation_signature(
                        self.program,
                        binding,
                        name,
                        args,
                        self.allow_moves,
                        expression.span,
                        self.diagnostics,
                    )
                });
                let target = if let Some(binding_type) = callable_binding {
                    match binding_type {
                        Type::Function { parameters, result } => {
                            if !type_arguments.is_empty() {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-T225",
                                    "function values do not accept type arguments",
                                    expression.span,
                                ));
                            }
                            if args.len() != parameters.len() {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-T204",
                                    format!(
                                        "`{name}` expects {} arguments, received {}",
                                        parameters.len(),
                                        args.len()
                                    ),
                                    expression.span,
                                ));
                            }
                            VerifierCallTarget::Ordinary(Some(
                                VerifierFunctionSignature::Specialized {
                                    params: parameters
                                        .into_iter()
                                        .enumerate()
                                        .map(|(index, ty)| crate::ast::Param {
                                            name: format!("argument{index}"),
                                            mode: ParamMode::Value,
                                            ty,
                                            span: expression.span,
                                        })
                                        .collect(),
                                    return_type: *result,
                                    implicit_unique_ownership: false,
                                },
                            ))
                        }
                        _ => {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T287",
                                format!("`{name}` is a bound value, not a function value"),
                                expression.span,
                            ));
                            VerifierCallTarget::Ordinary(None)
                        }
                    }
                } else if let Some(import) = native {
                    if !type_arguments.is_empty() || args.len() != import.params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-B107",
                            "Native Rust Interop declaration set is unsupported: scalar value signature required",
                            expression.span,
                        ));
                    }
                    for effect in &import.effects {
                        if !self.current.effects.contains(effect) {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-B107",
                                "Native Rust Interop declaration set is unsupported: effect or capability mismatch",
                                expression.span,
                            ));
                        }
                    }
                    VerifierCallTarget::Native(import)
                } else if let Some(op) = crate::map_ops::by_generic_name(name, type_arguments) {
                    let Some((params, return_type)) = op.ast_signature(type_arguments) else {
                        return Err(error(
                            self.program,
                            "SPX-T274",
                            "typed collection requires admitted key/value type arguments",
                            expression.span,
                        ));
                    };
                    if args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type,
                        implicit_unique_ownership: false,
                    }))
                } else if name == crate::vec_field::NAME {
                    let Some((params, return_type)) = super::super::vec_field::signature(
                        self.types,
                        type_arguments,
                        args,
                        expression.span,
                    ) else {
                        self.diagnostics.push(error(self.program,"SPX-T310","vec_field requires one admitted owned record type, a named Vec and usize index, and an exact literal field selector",expression.span));
                        self.values.push(None);
                        return Ok(());
                    };
                    if !self.current.type_parameters.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T310",
                            "vec_field is not admitted in generic function templates",
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type,
                        implicit_unique_ownership: false,
                    }))
                } else if name == crate::literal_format::NAME {
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            "string_format does not accept type arguments",
                            expression.span,
                        ));
                    }
                    if !self.current.type_parameters.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            "string_format is not admitted in generic function templates",
                            expression.span,
                        ));
                    }
                    let template = match args.first().map(|arg| &arg.kind) {
                        Some(ExprKind::String(value)) => value,
                        _ => {
                            self.diagnostics.push(error(self.program, "SPX-T204", "string_format requires a compile-time string literal as its first argument", expression.span));
                            self.values.push(None);
                            return Ok(());
                        }
                    };
                    let pieces = match crate::literal_format::scan(template) {
                        Ok(pieces) => pieces,
                        Err(reason) => {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T204",
                                reason.message(),
                                args[0].span,
                            ));
                            self.values.push(None);
                            return Ok(());
                        }
                    };
                    let fields = crate::literal_format::field_count(&pieces);
                    if args.len() - 1 != fields {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "string_format literal has {fields} fields, received {} values",
                                args.len() - 1
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::LiteralFormat
                } else if let Some(op) = crate::string_ops::by_name(name) {
                    // Compiler-owned string operations verify through
                    // the ordinary monomorphic machinery with one
                    // synthetic signature; consuming arguments use the
                    // established `own` transfer mode and borrowed
                    // arguments never mark their sources moved.
                    if op == crate::string_ops::StringOp::Take
                        && !crate::string_ops::take::source_operand(args, self.allow_moves)
                    {
                        self.diagnostics.push(error(self.program, "SPX-O105",
                            "string_take requires an available named owned String outside contracts", expression.span));
                    }
                    let params = crate::string_ops::ast_params(op);
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            format!("monomorphic function `{name}` does not accept type arguments"),
                            expression.span,
                        ));
                    }
                    if args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type: op.ast_return_type(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::str_ops::by_name(name) {
                    let params = crate::str_ops::ast_params(op);
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T225",
                            format!("monomorphic function `{name}` does not accept type arguments"),
                            expression.span,
                        ));
                    }
                    if args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params,
                        return_type: op.ast_return_type(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::vec_ops::by_name(name) {
                    if op == crate::vec_ops::VecOp::StrAt
                        && (!self.current.type_parameters.is_empty()
                            || crate::source_verify::string_slot::root(
                                type_arguments,
                                args,
                                &self.scopes[scope].bindings,
                            )
                            .is_none())
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T281",
                            crate::vec_ops::string_slot::SHAPE,
                            expression.span,
                        ));
                    }
                    let element = if op == crate::vec_ops::VecOp::StrAt {
                        Some(&Type::String)
                    } else {
                        type_arguments.first()
                    };
                    if (if op == crate::vec_ops::VecOp::StrAt { !type_arguments.is_empty() } else { type_arguments.len() != 1 })
                        || element.is_none_or(|ty| {
                            !crate::source_verify::declared_type::owned_leaf_collection::vec_operation_admitted(self.types, op, ty)
                                && !crate::vec_ops::source_parameter_is_admitted(self.program, self.current, op, ty)
                        })
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T281",
                            format!("vector operation `{name}` requires one explicit admitted type argument"),
                            expression.span,
                        ));
                    }
                    if args.len() != op.arity() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T281",
                            format!(
                                "vector operation `{name}` expects {} arguments, received {}",
                                op.arity(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    if op.capacity_argument().is_some_and(|index| {
                        matches!(args.get(index).map(|arg| &arg.kind), Some(ExprKind::Usize(value)) if *value > crate::vec_ops::MAX_CAPACITY)
                    })
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T282",
                            format!(
                                "`{name}` literal capacity must be no greater than {}",
                                crate::vec_ops::MAX_CAPACITY
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(element.map(|element| {
                        VerifierFunctionSignature::Specialized {
                            params: crate::vec_ops::ast_params_with_owned_element(
                                op,
                                element,
                                *element == crate::ast::Type::Bytes
                                    || crate::source_verify::declared_type::owned_leaf_collection::admitted(self.types, element)
                                    || crate::source_verify::declared_type::
                                        owned_leaf_collection::runtime_element(
                                            self.types, element,
                                        ),
                            ),
                            return_type: op.ast_return_type(element),
                            implicit_unique_ownership: false,
                        }
                    }))
                } else if let Some(op) = crate::list_ops::by_name(name) {
                    if !type_arguments.is_empty() || args.len() != op.argument_count() {
                        self.diagnostics.push(error(self.program, "SPX-T291", format!("immutable list operation `{name}` requires {} arguments and no type arguments", op.argument_count()), expression.span));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params: op.ast_params(),
                        return_type: op.ast_return_type(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::iterator_ops::by_name(name) {
                    let element = type_arguments.first();
                    if type_arguments.len() != 1
                        || args.len() != 1
                        || element.is_none_or(|ty| {
                            !crate::iterator_ops::ast_element_is_admitted(ty)
                                    && !crate::source_verify::declared_type::
                                        owned_leaf_collection::runtime_element(
                                            self.types,
                                            ty,
                                        )
                        })
                    {
                        self.diagnostics.push(error(self.program,"SPX-T290","iterator operations require one concrete scalar type argument and one owned argument",expression.span));
                    }
                    VerifierCallTarget::Ordinary(element.map(|element| {
                        VerifierFunctionSignature::Specialized {
                            params: crate::iterator_ops::ast_params(op, element),
                            return_type: op.ast_return_type(element),
                            implicit_unique_ownership: false,
                        }
                    }))
                } else if let Some(op) = crate::box_ops::by_name(name) {
                    let element = type_arguments.first();
                    if type_arguments.len() != 1
                        || element.is_none_or(|ty| {
                            !crate::box_ops::ast_operation_element_is_admitted(op, ty)
                                && !crate::box_ops::source_parameter_is_admitted(
                                    self.program,
                                    self.current,
                                    op,
                                    ty,
                                )
                        })
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T285",
                            format!("box operation `{name}` requires one explicit admitted type argument"),
                            expression.span,
                        ));
                    }
                    if args.len() != 1 {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T285",
                            format!(
                                "box operation `{name}` expects 1 argument, received {}",
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(element.map(|element| {
                        VerifierFunctionSignature::Specialized {
                            params: crate::box_ops::ast_params(op, element),
                            return_type: op.ast_return_type(element),
                            implicit_unique_ownership: false,
                        }
                    }))
                } else if let Some(op) = crate::byte_ops::by_name(name) {
                    if !type_arguments.is_empty() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T263",
                            format!("byte operation `{name}` does not accept type arguments"),
                            expression.span,
                        ));
                    }
                    if args.len() != op.arity() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T263",
                            format!(
                                "byte operation `{name}` expects {} arguments, received {}",
                                op.arity(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    if op.is_view()
                        && args.first().is_none_or(|argument| {
                            !source_byte_view_place_is_admitted(
                                op,
                                argument,
                                &self.scopes[scope].bindings,
                                self.types,
                            )
                        })
                    {
                        let diagnostic = error(
                            self.program,
                            "SPX-T266",
                            if matches!(
                                op,
                                crate::byte_ops::ByteOp::StringAsStr
                                    | crate::byte_ops::ByteOp::StrAsBytes
                            ) {
                                format!(
                                    "borrowed view `{name}` requires a named String owner or an authenticated named-record path to a String field"
                                )
                            } else {
                                format!(
                                    "borrowed view `{name}` requires an exact admitted storage place"
                                )
                            },
                            expression.span,
                        );
                        self.diagnostics.push(match args.first() {
                            Some(argument) => {
                                diagnostic.with_help(hints::view_place_help(name, argument))
                            }
                            None => diagnostic,
                        });
                    }
                    if op.is_owned_buffer_chain() {
                        let reopen = self
                            .buffer_reopen_sites
                            .contains(&(expression.span.start, expression.span.end));
                        self.diagnostics
                            .extend(crate::source_verify::owned_buffer::check_call(
                                self.program,
                                expression,
                                op,
                                name,
                                args,
                                reopen,
                            ));
                    }
                    VerifierCallTarget::Byte(op)
                } else if let Some(op) = crate::host_io_ops::by_name(name) {
                    let params = crate::host_io_ops::ast_params(op);
                    if !type_arguments.is_empty() || args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T269",
                            format!("invalid host I/O operation `{name}` call shape"),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::HostIo(op)
                } else if let Some(op) = crate::stdin_stream_ops::pure_by_name(name) {
                    if !type_arguments.is_empty() || args.len() != 1 {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T270",
                            "invalid streaming stdin inspection call shape",
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Specialized {
                        params: op.params(),
                        return_type: op.ast_result(),
                        implicit_unique_ownership: false,
                    }))
                } else if let Some(op) = crate::command_io_ops::by_name(name) {
                    let params = crate::command_io_ops::ast_params(op);
                    if !type_arguments.is_empty() || args.len() != params.len() {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T270",
                            format!("invalid command I/O operation `{name}` call shape"),
                            expression.span,
                        ));
                    }
                    VerifierCallTarget::CommandIo(op)
                } else {
                    let target = self.functions.get(name.as_str()).copied();
                    if target.is_none() {
                        self.diagnostics.push(hints::unknown_function(
                            self.program,
                            name,
                            self.functions,
                            expression.span,
                        ));
                    }
                    if target.is_some_and(|target| args.len() != target.params.len()) {
                        let target = target.expect("checked above");
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T204",
                            format!(
                                "`{name}` expects {} arguments, received {}",
                                target.params.len(),
                                args.len()
                            ),
                            expression.span,
                        ));
                    }
                    let specialized = target.and_then(|target| {
                        if target.type_parameters.is_empty() {
                            if !type_arguments.is_empty() {
                                self.diagnostics.push(error(
                                    self.program,
                                    "SPX-T225",
                                    format!("monomorphic function `{name}` does not accept type arguments"),
                                    expression.span,
                                ));
                                return None;
                            }
                            return Some(VerifierFunctionSignature::Borrowed(target));
                        }
                        let inferred_arguments;
                        let type_arguments = if type_arguments.is_empty() {
                            inferred_arguments = crate::source_verify::generic_inference::arguments(
                                self.program,
                                self.current,
                                target,
                                args,
                                &self.scopes[scope].bindings,
                                self.functions,
                                self.types,
                            );
                            inferred_arguments.as_deref().unwrap_or(type_arguments)
                        } else {
                            type_arguments
                        };
                        if type_arguments.len() != target.type_parameters.len() {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T225",
                                format!("generic function `{name}` expects {} explicit type arguments, received {}", target.type_parameters.len(), type_arguments.len()),
                                expression.span,
                            ).with_help(hints::generic_call_help(name)));
                            return None;
                        }
                        if !generic_function_arguments_are_admitted(target, type_arguments, self.types)
                            && !generic_function_arguments_are_forwarded(
                                self.current,
                                target,
                                type_arguments,
                            )
                            && !crate::vec_ops::source_arguments_are_admitted(
                                self.program,
                                target,
                                type_arguments,
                            )
                            && !crate::box_ops::source_arguments_are_admitted(self.program, target, type_arguments)
                        {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T225",
                                format!("generic function `{name}` accepts only direct `i64` or `bool` type arguments, except admitted Copy scalars in an owned-record relay"),
                                expression.span,
                            ));
                            return None;
                        }
                        validation_specialize_signature(target, type_arguments).map(
                            |(params, return_type)| {
                                VerifierFunctionSignature::Specialized {
                                    params,
                                    return_type,
                                    implicit_unique_ownership: true,
                                }
                            },
                        )
                    });
                    VerifierCallTarget::Ordinary(specialized)
                };
                if let VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Borrowed(
                    function,
                ))) = &target
                {
                    self.note_row_loan_arguments(function, args, scope);
                }
                let borrowed_bytes_loans = match &target {
                    VerifierCallTarget::Ordinary(Some(VerifierFunctionSignature::Borrowed(
                        function,
                    ))) => activate_borrowed_bytes_call_loans(
                        self.program,
                        args,
                        &function.params,
                        &mut self.scopes[scope].bindings,
                        self.types,
                    ),
                    VerifierCallTarget::Ordinary(Some(
                        VerifierFunctionSignature::Specialized { params, .. },
                    )) if params.iter().any(|p| {
                        crate::source_verify::declared_type::collection_record::vector(
                            self.types, &p.ty,
                        )
                    }) =>
                    {
                        activate_borrowed_bytes_call_loans(
                            self.program,
                            args,
                            params,
                            &mut self.scopes[scope].bindings,
                            self.types,
                        )
                    }
                    _ => Vec::new(),
                };
                if let Some(argument) = args.first() {
                    self.frames.push(VerifierFrame::ResumeCallArgument {
                        expression,
                        name,
                        args,
                        scope,
                        index: 0,
                        target,
                        borrowed_bytes_loans,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: argument,
                        scope,
                    });
                } else {
                    self.values.push(Some(match target {
                        VerifierCallTarget::LiteralFormat => {
                            CheckedValue::returned(Type::String, true)
                        }
                        VerifierCallTarget::Native(import) => {
                            let mut value = CheckedValue::returned(
                                import.result.value_type(),
                                import.result.is_owned(),
                            );
                            value.native_unit = import.result == ImportResult::Unit;
                            value
                        }
                        VerifierCallTarget::Byte(op) => {
                            let ty = op.ast_return_type();
                            let owns = self.types.needs_drop(&ty);
                            CheckedValue::returned(ty, owns)
                        }
                        VerifierCallTarget::HostIo(op) => {
                            CheckedValue::returned(op.ast_return_type(), false)
                        }
                        VerifierCallTarget::CommandIo(op) => CheckedValue {
                            ty: crate::command_io_ops::ast_return_type(op),
                            mode: match op {
                                crate::hir::ResolvedHostCommandOperation::ArgUtf8 => {
                                    ParamMode::Borrow
                                }
                                crate::hir::ResolvedHostCommandOperation::StdinRead => {
                                    ParamMode::Own
                                }
                                crate::hir::ResolvedHostCommandOperation::ArgsLen
                                | crate::hir::ResolvedHostCommandOperation::StderrWrite
                                | crate::hir::ResolvedHostCommandOperation::StdoutAppend
                                | crate::hir::ResolvedHostCommandOperation::StderrAppend => {
                                    ParamMode::Value
                                }
                                operation => {
                                    match crate::command_io_ops::result_ownership(operation) {
                                        crate::hir::OwnershipMode::Own => ParamMode::Own,
                                        crate::hir::OwnershipMode::Borrow => ParamMode::Borrow,
                                        _ => ParamMode::Value,
                                    }
                                }
                            },
                            native_unit: false,
                        },
                        VerifierCallTarget::Ordinary(Some(target)) => CheckedValue::returned(
                            target.return_type().clone(),
                            self.types.needs_drop(target.return_type()),
                        ),
                        VerifierCallTarget::Ordinary(None) => {
                            self.values.push(None);
                            return Ok(());
                        }
                    }));
                }
            }
            ExprKind::MethodCall {
                receiver,
                method,
                type_arguments,
                args,
                ..
            } => {
                if !type_arguments.is_empty() {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T225",
                        format!("method `{method}` does not accept type arguments in this slice"),
                        expression.span,
                    ));
                }
                self.frames.push(VerifierFrame::ResumeMethodReceiver {
                    expression,
                    receiver,
                    method,
                    args,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: receiver,
                    scope,
                });
            }
            // These walkers only traverse generic-function and contract
            // expressions; `super` is meaningful only inside a class-method
            // override, whose body is resolved by the HIR layer instead.
            ExprKind::SuperMethod { method_span, .. } => {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T231",
                    "`super` is only allowed inside a class-method override",
                    *method_span,
                ));
                self.values.push(None);
            }
            ExprKind::If {
                condition,
                then_branch,
                else_branch,
            } => {
                self.frames.push(VerifierFrame::ResumeIfCondition {
                    expression,
                    then_branch,
                    else_branch,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: condition,
                    scope,
                });
            }
            ExprKind::Block { statements, tail } => {
                let outer_names = self.scopes[scope]
                    .bindings
                    .keys()
                    .cloned()
                    .collect::<Vec<_>>();
                let block_scope = self.scopes.len();
                self.recovery.fork(Some(scope), block_scope);
                self.scopes.push(VerifierScope {
                    bindings: self.scopes[scope].bindings.clone(),
                    local_borrow_count: self.scopes[scope].local_borrow_count,
                });
                if let Some(first_statement) = statements.first() {
                    if let Statement::Let {
                        name, name_span, ..
                    } = first_statement
                    {
                        if !source_identifier(name) {
                            self.diagnostics.push(hints::reserved_local_binding(
                                self.program,
                                name,
                                *name_span,
                            ));
                        }
                    }
                    if let Statement::While {
                        condition, body, ..
                    } = first_statement
                    {
                        self.begin_while_statement(
                            expression,
                            statements,
                            tail,
                            scope,
                            block_scope,
                            0,
                            outer_names,
                            condition,
                            body,
                        );
                    } else if let Statement::For {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    }
                    | Statement::ForBorrow {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    }
                    | Statement::ForOwn {
                        item,
                        item_span,
                        values,
                        body,
                        ..
                    } = first_statement
                    {
                        self.begin_for_statement(
                            expression,
                            statements,
                            tail,
                            scope,
                            block_scope,
                            0,
                            outer_names,
                            item,
                            *item_span,
                            values,
                            body,
                        );
                    } else {
                        self.check_string_replacement_entry(first_statement, block_scope);
                        self.note_owned_buffer_reopen(first_statement);
                        self.frames.push(VerifierFrame::ResumeBlockStatement {
                            expression,
                            statements,
                            tail,
                            parent_scope: scope,
                            block_scope,
                            index: 0,
                            outer_names,
                            recovery_checkpoint: self.recovery.checkpoint(self.diagnostics),
                        });
                        self.frames.push(VerifierFrame::Enter {
                            expression: first_statement.value(),
                            scope: block_scope,
                        });
                    }
                } else {
                    self.frames.push(VerifierFrame::ResumeBlockTail {
                        parent_scope: scope,
                        block_scope,
                        outer_names,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: tail,
                        scope: block_scope,
                    });
                }
            }
            // Resumable Effects v1 (issue #204). See
            // `iterative::calls::frame_resume_yield`.
            ExprKind::Yield { request } => {
                self.frames.push(VerifierFrame::ResumeYield {
                    expression,
                    request,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: request,
                    scope,
                });
            }
            ExprKind::Try { operand } => {
                self.frames.push(VerifierFrame::ResumeTry {
                    expression,
                    operand,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: operand,
                    scope,
                });
            }
            ExprKind::Project { base, field, .. } => {
                if let Some((root, value)) = crate::source_verify::record_traversal::project(
                    expression,
                    &self.scopes[scope].bindings,
                    self.types,
                ) {
                    let owner = Expr {
                        kind: ExprKind::Var(root),
                        span: expression.span,
                    };
                    if let Some(place) =
                        source_place(&owner, &self.scopes[scope].bindings, self.types)
                    {
                        check_source_place_availability(
                            self.program,
                            &place,
                            &self.scopes[scope].bindings,
                            expression.span,
                            self.diagnostics,
                        );
                    }
                    self.values.push(Some(value));
                    return Ok(());
                }
                let rooted_string_view = matches!(
                    self.frames.last(),
                    Some(VerifierFrame::ResumeCallArgument {
                        target: VerifierCallTarget::Byte(crate::byte_ops::ByteOp::StringAsStr),
                        ..
                    })
                ) && source_byte_view_place_is_admitted(
                    crate::byte_ops::ByteOp::StringAsStr,
                    expression,
                    &self.scopes[scope].bindings,
                    self.types,
                );
                if self.loop_depth != 0 && !rooted_string_view
                    && source_place(base, &self.scopes[scope].bindings, self.types).is_some_and(
                        |place| {
                            !crate::source_verify::declared_type::owned_leaf_collection::copy_or_leaf_admitted(
                                self.types, &place.ty,
                            ) && !crate::source_verify::declared_type::collection_record::admitted(&place.ty, self.types)
                        },
                    )
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T252",
                        "record field projection is not yet admitted in while bodies",
                        expression.span,
                    ));
                }
                if let Some(place) =
                    source_place(expression, &self.scopes[scope].bindings, self.types)
                {
                    check_source_place_availability(
                        self.program,
                        &place,
                        &self.scopes[scope].bindings,
                        expression.span,
                        self.diagnostics,
                    );
                    self.values.push(Some(CheckedValue {
                        ty: place.ty,
                        mode: place.mode,
                        native_unit: false,
                    }));
                } else {
                    self.frames.push(VerifierFrame::ResumeProject {
                        expression,
                        base,
                        field,
                    });
                    self.frames.push(VerifierFrame::Enter {
                        expression: base,
                        scope,
                    });
                }
            }
            ExprKind::ConstructRecord {
                type_name,
                type_arguments,
                fields,
                ..
            } => {
                if matches!(type_name.as_str(), "Map" | "Set") {
                    return Err(error(
                        self.program,
                        "SPX-T274",
                        "collections can only be created by map_new/set_new",
                        expression.span,
                    ));
                }
                if type_name == "Iter" {
                    return Err(error(
                        self.program,
                        "SPX-T290",
                        "Iter carriers can only be created by vec_into_iter",
                        expression.span,
                    ));
                }
                let instance = Type::Named {
                    name: type_name.clone(),
                    arguments: type_arguments.clone(),
                };
                let reported = self.diagnostics.len();
                check_declared_type(
                    self.program,
                    &instance,
                    expression.span,
                    self.types,
                    &HashSet::new(),
                    self.diagnostics,
                );
                let declared_fields = effective_record_fields(self.types, &instance);
                if declared_fields.is_none()
                    && !self.diagnostics[reported..]
                        .iter()
                        .any(|diagnostic| diagnostic.severity.is_error())
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T215",
                        format!("`{type_name}` is not a declared record type"),
                        expression.span,
                    ));
                }
                if !fields.is_empty() {
                    self.frames.push(VerifierFrame::PrepareRecordField {
                        expression,
                        type_name,
                        type_arguments,
                        fields,
                        declared_fields,
                        scope,
                        index: 0,
                        supplied: HashSet::new(),
                    });
                } else {
                    if let Some(declared_fields) = declared_fields {
                        for field in declared_fields {
                            self.diagnostics.push(error(
                                self.program,
                                "SPX-T213",
                                format!(
                                    "record `{type_name}` construction is missing field `{}`",
                                    field.name
                                ),
                                expression.span,
                            ));
                        }
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else {
                        self.values.push(None);
                    }
                }
            }
            ExprKind::ConstructVariant {
                type_name,
                type_arguments,
                case_name,
                fields,
                ..
            } => {
                let declaration = self.types.declaration(type_name);
                let instance = Type::Named {
                    name: type_name.clone(),
                    arguments: type_arguments.clone(),
                };
                check_declared_type(
                    self.program,
                    &instance,
                    expression.span,
                    self.types,
                    &HashSet::new(),
                    self.diagnostics,
                );
                let cases = declaration.and_then(|declaration| match &declaration.kind {
                    TypeDeclarationKind::Variant { cases } => Some(cases.as_slice()),
                    TypeDeclarationKind::Resource { .. }
                    | TypeDeclarationKind::Record { .. }
                    | TypeDeclarationKind::Class { .. } => None,
                });
                let case =
                    cases.and_then(|cases| cases.iter().find(|case| case.name == *case_name));
                if cases.is_none() || case.is_none() {
                    let diagnostic = error(
                        self.program,
                        "SPX-T215",
                        format!("`{type_name}::{case_name}` is not a declared variant constructor"),
                        expression.span,
                    );
                    self.diagnostics.push(
                        match cases.and_then(|cases| {
                            crate::source_verify::hints::nearest_variant_case_name(case_name, cases)
                        }) {
                            Some(nearest) => diagnostic.with_help(format!(
                                "did you mean `{type_name}::{nearest} {{ ... }}`?"
                            )),
                            None => diagnostic,
                        },
                    );
                }
                if !fields.is_empty() {
                    self.frames.push(VerifierFrame::PrepareVariantField {
                        expression,
                        type_name,
                        type_arguments,
                        case_name,
                        fields,
                        declaration,
                        case,
                        scope,
                        index: 0,
                        supplied: HashSet::new(),
                    });
                } else {
                    if let Some(case) = case {
                        for field in &case.fields {
                            self.diagnostics.push(error(self.program, "SPX-T213", format!("variant construction `{type_name}::{case_name}` is missing payload field `{}`", field.name), expression.span));
                        }
                        // Ownership belongs to the complete variant carrier, not
                        // only to the selected case. A zero-payload case of a
                        // variant whose other cases contain owned fields is still
                        // a fresh owned carrier and must cross return/call
                        // boundaries exactly once.
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else if cases.is_some() {
                        self.values.push(Some(CheckedValue::returned(
                            instance.clone(),
                            self.types.needs_drop(&instance),
                        )));
                    } else {
                        self.values.push(None);
                    }
                }
            }
            ExprKind::UpdateRecord { base, fields } => {
                self.frames.push(VerifierFrame::ResumeUpdateBase {
                    expression,
                    base,
                    fields,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: base,
                    scope,
                });
            }
            ExprKind::Match {
                scrutinee, arms, ..
            } => {
                self.frames.push(VerifierFrame::ResumeMatchScrutinee {
                    expression,
                    scrutinee,
                    arms,
                    scope,
                });
                self.frames.push(VerifierFrame::Enter {
                    expression: scrutinee,
                    scope,
                });
            }
        }
        Ok(())
    }
}

//! Ordinary return publishes no intermediate expression value.
use super::*;
use crate::ast::ParamMode;
use crate::source_verify::loans::mark_value_sources_moved;
impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn resume_lexical_return(
        &mut self,
        expression: &'p Expr,
        operand: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let value = self.values.pop().unwrap_or(None);
        if let Some(value) = value {
            if value.native_unit
                || (value.ty != self.current.return_type
                    && !self.recovery.explains(operand, &self.current.return_type))
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T103",
                    "lexical return operand differs from the function result type",
                    operand.span,
                ));
            }
            if self.types.needs_drop(&value.ty) && value.mode != ParamMode::Own {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-O104",
                    "lexical return must transfer an owned result",
                    operand.span,
                ));
            }
            if !self.allow_moves {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T312",
                    "return is only admitted in the executable function body",
                    expression.span,
                ));
            } else if self.types.needs_drop(&value.ty) {
                mark_value_sources_moved(
                    self.program,
                    operand,
                    &mut self.scopes[scope].bindings,
                    self.types,
                    self.diagnostics,
                );
            }
            self.values.push(Some(CheckedValue::value(Type::Never)));
        } else {
            self.values.push(None);
        }
        Ok(())
    }
}

//! Record, variant, and scalar match arm frames: per-arm scope handling and
//! the joins that produce the match's value.

use crate::ast::{MatchMode, MatchPattern, ParamMode, Type};
use crate::diagnostic::Diagnostic;
use crate::source_verify::IterativeVerifier;
use crate::source_verify::binding::{Availability, Binding};
use crate::source_verify::declared_type::generic_function_has_owned_record_composition;
use crate::source_verify::diagnostics::{
    error, reject_aggregate_match_result, reject_native_unit_value, source_identifier,
};
use crate::source_verify::loans::merge_moved;
use crate::source_verify::place::{join_definitely_partial, join_moved_places};
use crate::source_verify::private_names::{missing_case, type_name};
use crate::source_verify::scope::{
    ScalarMatchState, VariantMatchState, VerifierFrame, VerifierScope,
};
use crate::source_verify::type_table::TypeTable;
use crate::source_verify::variant_or::{
    AGGREGATE_REFUTABLE_HELP, VariantOrContext, check_variant_or_pattern,
};
use std::collections::{BTreeSet, HashMap, HashSet};

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn frame_resume_record_match_arm(
        &mut self,
        arm: &'p crate::ast::MatchArm,
        parent_scope: usize,
        arm_scope: usize,
        outer_names: Vec<String>,
        owns_record_input: bool,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "record match arm scope is not the active child",
            ));
        }
        let result = self.values.pop().unwrap_or(None);
        if let Some(value) = &result {
            reject_native_unit_value(self.program, &arm.value, value, self.diagnostics);
        }
        let arm_bindings = self
            .scopes
            .pop()
            .expect("record arm scope is active")
            .bindings;
        merge_moved(
            &mut self.scopes[parent_scope].bindings,
            &arm_bindings,
            &outer_names,
        );
        let generic_template = self.functions.get(self.current.name.as_str()).copied();
        let generic_owned_result = generic_template.is_some_and(|function| {
            generic_function_has_owned_record_composition(function, self.types)
        });
        if result.as_ref().is_some_and(|value| {
            value.ty!=Type::Never && (!matches!(value.ty, Type::I64 | Type::Bool) || value.mode != ParamMode::Value)
                && !(generic_template.is_some_and(|function| function.type_parameters.is_empty())
                    && (value.mode == ParamMode::Value || owns_record_input)
                    && crate::source_verify::declared_type::ordinary_record_match_result(&value.ty, value.mode, self.types))
                && !(generic_owned_result
                    && (((value.ty == self.current.return_type || (self.types.is_nested_owned_byte_record(&value.ty) || crate::source_verify::declared_type::string_record::runtime_admitted(&value.ty, self.types))) && value.mode == ParamMode::Own)
                        || (value.mode == ParamMode::Value
                            && (crate::source_verify::type_table::owned_byte_record_copy_field_is_admitted(&value.ty)
                                || matches!(&value.ty, Type::Named { name, arguments }
                                    if arguments.is_empty() && generic_template.is_some_and(|function| function.type_parameters.iter().any(|parameter| parameter.name == *name)))))))
        }) {
            self.diagnostics.push(error(
                self.program,
                "SPX-T216",
                "record match arm must return a Copy i64 or bool value",
                arm.value.span,
            ));
            self.values.push(None);
        } else {
            self.values.push(result);
        }
        Ok(())
    }

    pub(super) fn frame_prepare_variant_match_arm(
        &mut self,
        mut state: VariantMatchState<'p>,
    ) -> Result<(), Diagnostic> {
        #[cfg(test)]
        if self.recovery_legacy {
            return self.recovery_old_frame_prepare_variant_match_arm(state);
        }
        if state.index >= state.arms.len() {
            if !state.wildcard_seen {
                if let (Some(variant_name), Some(cases)) =
                    (&state.variant_name, state.declared_cases)
                {
                    if let Some(missing) = cases
                        .iter()
                        .find(|case| !state.covered.contains(&case.name))
                    {
                        self.diagnostics.push(missing_case(
                            self.program,
                            self.types,
                            variant_name,
                            &missing.name,
                            !missing.fields.is_empty(),
                            state.expression.span,
                        ));
                    }
                }
            }
            if let Some((first, rest)) = state.arm_states.split_first() {
                let mut joined = first.clone();
                for branch in rest {
                    for name in &state.outer_names {
                        if let (Some(joined_binding), Some(branch_binding)) =
                            (joined.get_mut(name), branch.get(name))
                        {
                            joined_binding.availability = joined_binding
                                .availability
                                .join(branch_binding.availability);
                            joined_binding.moved_places =
                                join_moved_places(joined_binding, branch_binding);
                            joined_binding.definitely_partial =
                                join_definitely_partial(joined_binding, branch_binding);
                        }
                    }
                }
                merge_moved(
                    &mut self.scopes[state.parent_scope].bindings,
                    &joined,
                    &state.outer_names,
                );
            }
            self.values.push(state.result);
            return Ok(());
        }
        let arm = &state.arms[state.index];
        let arm_scope = self.scopes.len();
        self.recovery.fork(Some(state.parent_scope), arm_scope);
        self.scopes.push(VerifierScope {
            bindings: state.baseline.clone(),
            local_borrow_count: state
                .baseline
                .values()
                .filter(|binding| binding.borrow_origin.is_some())
                .count(),
        });
        match &arm.pattern {
            MatchPattern::Wildcard { span } => {
                if state.mode != MatchMode::Value {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O117",
                        "explicit ownership variant match requires every case pattern",
                        *span,
                    ));
                }
                if state.wildcard_seen
                    || state
                        .declared_cases
                        .is_some_and(|cases| state.covered.len() == cases.len())
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-M102",
                        "unreachable wildcard match arm",
                        *span,
                    ));
                }
                state.wildcard_seen = arm.guard.is_none();
            }
            MatchPattern::Variant {
                type_name,
                case_name,
                fields,
                span,
                ..
            } => {
                let checkpoint = self.recovery.checkpoint(self.diagnostics);
                let compatible = state.variant_name.as_deref() == Some(type_name);
                let declared_case = compatible
                    .then_some(state.declared_cases)
                    .flatten()
                    .and_then(|cases| cases.iter().find(|case| case.name == *case_name));
                if declared_case.is_none() {
                    let diagnostic = error(
                        self.program,
                        "SPX-M103",
                        format!(
                            "pattern `{type_name}::{case_name}` is incompatible with the match scrutinee"
                        ),
                        *span,
                    );
                    self.diagnostics.push(
                        match compatible
                            .then_some(state.declared_cases)
                            .flatten()
                            .and_then(|cases| {
                                crate::source_verify::hints::nearest_variant_case_name(
                                    case_name, cases,
                                )
                            }) {
                            Some(nearest) => diagnostic.with_help(format!(
                                "did you mean `{type_name}::{nearest} {{ ... }}`?"
                            )),
                            None => diagnostic,
                        },
                    );
                } else if state.wildcard_seen
                    || state.covered.contains(case_name)
                    || (arm.guard.is_none() && !state.covered.insert(case_name.clone()))
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-M102",
                        format!("unreachable duplicate case `{type_name}::{case_name}`"),
                        *span,
                    ));
                }
                let mut supplied = HashSet::new();
                let mut bindings = HashSet::new();
                for field in fields {
                    let declared_field = declared_case.and_then(|case| {
                        case.fields
                            .iter()
                            .find(|candidate| candidate.name == field.name)
                    });
                    if !supplied.insert(field.name.as_str())
                        || (declared_case.is_some() && declared_field.is_none())
                    {
                        self.diagnostics.push(error(self.program, "SPX-M104", format!("unknown or duplicate pattern field `{}` in `{type_name}::{case_name}`", field.name), field.span));
                    }
                    if !source_identifier(&field.binding)
                        || !bindings.insert(field.binding.as_str())
                        || self.scopes[arm_scope].bindings.contains_key(&field.binding)
                    {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-M104",
                            format!("invalid or duplicate pattern binding `{}`", field.binding),
                            field.binding_span,
                        ));
                        continue;
                    }
                    if let Some(declared_field) = declared_field {
                        let binding_ty = state
                            .variant_name
                            .as_ref()
                            .and_then(|name| {
                                self.types.declaration(name).and_then(|declaration| {
                                    TypeTable::substitute_variant_type(
                                        declaration,
                                        &state.variant_arguments,
                                        &declared_field.ty,
                                    )
                                })
                            })
                            .unwrap_or_else(|| declared_field.ty.clone());
                        let binding_mode = if self.types.needs_drop(&binding_ty) {
                            match state.mode {
                                MatchMode::Own => ParamMode::Own,
                                MatchMode::Borrow => ParamMode::Borrow,
                                MatchMode::Value => ParamMode::Value,
                            }
                        } else {
                            ParamMode::Value
                        };
                        self.scopes[arm_scope].bindings.insert(
                            field.binding.clone(),
                            Binding {
                                contract_local: false,
                                traversal_row: None,
                                ty: binding_ty,
                                mode: binding_mode,
                                availability: Availability::Available,
                                moved_places: HashMap::new(),
                                definitely_partial: HashSet::new(),
                                native_unit_discard: false,
                                mutable: false,
                                active_loans: BTreeSet::new(),
                                borrow_origin: None,
                            },
                        );
                    } else {
                        self.recovery.refused_let(
                            arm_scope,
                            &field.binding,
                            checkpoint,
                            self.diagnostics,
                        );
                    }
                }
                if let Some(declared_case) = declared_case {
                    for field in &declared_case.fields {
                        if !supplied.contains(field.name.as_str()) {
                            self.diagnostics.push(error(self.program, "SPX-M104", format!("pattern `{type_name}::{case_name}` is missing payload field `{}`", field.name), *span));
                        }
                    }
                }
            }
            MatchPattern::Record { span, .. } => self.diagnostics.push(error(
                self.program,
                "SPX-M103",
                "record pattern is incompatible with a variant scrutinee",
                *span,
            )),
            MatchPattern::Or { alternatives, span } => {
                let context = VariantOrContext {
                    variant_name: state.variant_name.as_deref(),
                    declared_cases: state.declared_cases,
                    mode: state.mode,
                    wildcard_seen: state.wildcard_seen,
                };
                let mut covered = state.covered.clone();
                check_variant_or_pattern(
                    self.program,
                    alternatives,
                    *span,
                    &context,
                    &mut |case| covered.insert(case.to_owned()),
                    self.diagnostics,
                );
                if arm.guard.is_none() {
                    state.covered = covered;
                }
            }
            MatchPattern::Literal { span, .. } | MatchPattern::Binding { span, .. } => {
                self.diagnostics.push(
                    error(
                        self.program,
                        "SPX-T254",
                        "refutable patterns are incompatible with an aggregate variant \
                         scrutinee",
                        *span,
                    )
                    .with_help(AGGREGATE_REFUTABLE_HELP),
                );
            }
        }
        let next = if let Some(guard) = &arm.guard {
            if !crate::source_verify::variant_guards::guard_shape(
                guard,
                &self.scopes[arm_scope].bindings,
            ) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T254",
                    "Copy variant guards require an ordinary Boolean expression without yield, closure, unsafe or residual propagation",
                    guard.span,
                ));
            }
            state.guard_pending = true;
            guard.as_ref()
        } else {
            &arm.value
        };
        self.frames
            .push(VerifierFrame::ResumeVariantMatchArm { state, arm_scope });
        self.frames.push(VerifierFrame::Enter {
            expression: next,
            scope: arm_scope,
        });
        Ok(())
    }

    pub(super) fn frame_resume_variant_match_arm(
        &mut self,
        mut state: VariantMatchState<'p>,
        arm_scope: usize,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "variant match arm scope is not the active child",
            ));
        }
        let arm = &state.arms[state.index];
        if state.guard_pending {
            let guard_value = self.values.pop().unwrap_or(None);
            if let Some(value) = guard_value {
                if (value.ty != Type::Bool
                    && !self
                        .recovery
                        .explains(arm.guard.as_ref().expect("guard retained"), &Type::Bool))
                    || value.mode != ParamMode::Value
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T256",
                        format!("match guard must be bool; received {}", value.ty),
                        arm.guard.as_ref().expect("guard retained").span,
                    ));
                }
            }
            if !crate::source_verify::variant_guards::ownership_unchanged(
                &state.baseline,
                &self.scopes[arm_scope].bindings,
            ) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T254",
                    "Copy variant guard changes surrounding ownership",
                    arm.guard.as_ref().expect("guard retained").span,
                ));
            }
            state.guard_pending = false;
            self.frames
                .push(VerifierFrame::ResumeVariantMatchArm { state, arm_scope });
            self.frames.push(VerifierFrame::Enter {
                expression: &arm.value,
                scope: arm_scope,
            });
            return Ok(());
        }
        let arm_value = self.values.pop().unwrap_or(None);
        let exits = arm_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(&arm.value);
        let collection_result = |ty: &Type, mode: ParamMode| {
            state.variant_name.as_ref().is_some_and(|name| {
                crate::source_verify::declared_type::collection_outcome::match_result(
                    self.types,
                    &Type::Named {
                        name: name.clone(),
                        arguments: state.variant_arguments.clone(),
                    },
                    state.mode,
                    ty,
                    mode,
                )
            })
        };
        if let Some(value) = &arm_value {
            reject_native_unit_value(self.program, &arm.value, value, self.diagnostics);
            if value.ty != Type::Never
                && !collection_result(&value.ty, value.mode)
                && !crate::source_verify::declared_type::generic_variant::match_result(
                    self.functions.get(self.current.name.as_str()).copied(),
                    self.types,
                    state.mode,
                    &value.ty,
                    value.mode,
                )
            {
                reject_aggregate_match_result(self.program, &arm.value, value, self.diagnostics);
            }
        }
        if let Some(arm_value) = arm_value {
            if arm_value.ty != Type::Never
                && state.needs_drop
                && !collection_result(&arm_value.ty, arm_value.mode)
                && !crate::source_verify::declared_type::generic_variant::match_result(
                    self.functions.get(self.current.name.as_str()).copied(),
                    self.types,
                    state.mode,
                    &arm_value.ty,
                    arm_value.mode,
                )
                && (state.mode == MatchMode::Value
                    || !matches!(arm_value.ty, Type::I64 | Type::Bool)
                    || arm_value.mode != ParamMode::Value)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T216",
                    "owned variant match arms must return a Copy i64 or bool value",
                    arm.value.span,
                ));
            }
            if let Some(expected) = &state.result {
                if expected.ty != Type::Never
                    && arm_value.ty != Type::Never
                    && (expected.ty != arm_value.ty || expected.mode != arm_value.mode)
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T216",
                        format!(
                            "match arms return incompatible values: {} and {}",
                            type_name(self.program, self.types, &expected.ty),
                            type_name(self.program, self.types, &arm_value.ty)
                        ),
                        arm.value.span,
                    ));
                }
            }
            if state
                .result
                .as_ref()
                .is_none_or(|value| value.ty == Type::Never)
            {
                state.result = Some(arm_value);
            }
        }
        let bindings = self
            .scopes
            .pop()
            .expect("variant arm scope is active")
            .bindings;
        if !exits {
            state.arm_states.push(bindings);
        }
        state.index += 1;
        self.frames
            .push(VerifierFrame::PrepareVariantMatchArm(state));
        Ok(())
    }

    pub(super) fn frame_prepare_scalar_match_arm(
        &mut self,
        state: ScalarMatchState<'p>,
    ) -> Result<(), Diagnostic> {
        if state.index >= state.arms.len() {
            if let Some((first, rest)) = state.arm_states.split_first() {
                let mut joined = first.clone();
                for branch in rest {
                    for name in &state.outer_names {
                        if let (Some(joined_binding), Some(branch_binding)) =
                            (joined.get_mut(name), branch.get(name))
                        {
                            joined_binding.availability = joined_binding
                                .availability
                                .join(branch_binding.availability);
                            joined_binding.moved_places =
                                join_moved_places(joined_binding, branch_binding);
                            joined_binding.definitely_partial =
                                join_definitely_partial(joined_binding, branch_binding);
                        }
                    }
                }
                merge_moved(
                    &mut self.scopes[state.parent_scope].bindings,
                    &joined,
                    &state.outer_names,
                );
            }
            self.values.push(state.result);
            return Ok(());
        }
        let arm = &state.arms[state.index];
        let arm_scope = self.scopes.len();
        self.recovery.fork(Some(state.parent_scope), arm_scope);
        self.scopes.push(VerifierScope {
            bindings: state.baseline.clone(),
            local_borrow_count: state
                .baseline
                .values()
                .filter(|binding| binding.borrow_origin.is_some())
                .count(),
        });
        match &arm.pattern {
            MatchPattern::Wildcard { .. } => {}
            MatchPattern::Binding { name, span } => {
                if !source_identifier(name) || self.scopes[arm_scope].bindings.contains_key(name) {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-M104",
                        format!("invalid or duplicate pattern binding `{name}`"),
                        *span,
                    ));
                } else {
                    self.scopes[arm_scope].bindings.insert(
                        name.clone(),
                        Binding {
                            contract_local: false,
                            traversal_row: None,
                            ty: state.scrutinee_ty.clone(),
                            mode: ParamMode::Value,
                            availability: Availability::Available,
                            moved_places: HashMap::new(),
                            definitely_partial: HashSet::new(),
                            native_unit_discard: false,
                            mutable: false,
                            active_loans: BTreeSet::new(),
                            borrow_origin: None,
                        },
                    );
                }
            }
            // Literal/or diagnostics fired during admission; the
            // arm value still checks so downstream errors stay
            // deterministic.
            _ => {}
        }
        match &arm.guard {
            Some(guard) => {
                self.frames
                    .push(VerifierFrame::ResumeScalarMatchGuard { state, arm_scope });
                self.frames.push(VerifierFrame::Enter {
                    expression: guard.as_ref(),
                    scope: arm_scope,
                });
            }
            None => {
                self.frames
                    .push(VerifierFrame::ResumeScalarMatchArm { state, arm_scope });
                self.frames.push(VerifierFrame::Enter {
                    expression: &arm.value,
                    scope: arm_scope,
                });
            }
        }
        Ok(())
    }

    pub(super) fn frame_resume_scalar_match_guard(
        &mut self,
        state: ScalarMatchState<'p>,
        arm_scope: usize,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "scalar match guard scope is not the active child",
            ));
        }
        let guard_value = self.values.pop().unwrap_or(None);
        let arm = &state.arms[state.index];
        if let Some(value) = &guard_value {
            if (value.ty != Type::Bool
                && !arm
                    .guard
                    .as_ref()
                    .is_some_and(|guard| self.recovery.explains(guard, &Type::Bool)))
                || value.mode != ParamMode::Value
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T256",
                    format!("match guard must be bool; received {}", value.ty),
                    arm.guard.as_ref().map_or(arm.span, |guard| guard.span),
                ));
            }
        }
        // The arm value observes the guard's moves within this
        // arm only.
        self.frames
            .push(VerifierFrame::ResumeScalarMatchArm { state, arm_scope });
        self.frames.push(VerifierFrame::Enter {
            expression: &arm.value,
            scope: arm_scope,
        });
        Ok(())
    }

    pub(super) fn frame_resume_scalar_match_arm(
        &mut self,
        mut state: ScalarMatchState<'p>,
        arm_scope: usize,
    ) -> Result<(), Diagnostic> {
        if arm_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "scalar match arm scope is not the active child",
            ));
        }
        let arm = &state.arms[state.index];
        let arm_value = self.values.pop().unwrap_or(None);
        let exits = arm_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(&arm.value);
        if let Some(value) = &arm_value {
            reject_native_unit_value(self.program, &arm.value, value, self.diagnostics);
            reject_aggregate_match_result(self.program, &arm.value, value, self.diagnostics);
        }
        if let Some(arm_value) = arm_value {
            if let Some(expected) = &state.result {
                if expected.ty != Type::Never
                    && arm_value.ty != Type::Never
                    && (expected.ty != arm_value.ty || expected.mode != arm_value.mode)
                {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T259",
                        format!(
                            "match arms return incompatible values: {} and {}",
                            type_name(self.program, self.types, &expected.ty),
                            type_name(self.program, self.types, &arm_value.ty)
                        ),
                        arm.value.span,
                    ));
                }
            }
            if state
                .result
                .as_ref()
                .is_none_or(|value| value.ty == Type::Never)
            {
                state.result = Some(arm_value);
            }
        }
        let bindings = self
            .scopes
            .pop()
            .expect("scalar arm scope is active")
            .bindings;
        if !exits {
            state.arm_states.push(bindings);
        }
        state.index += 1;
        self.frames
            .push(VerifierFrame::PrepareScalarMatchArm(state));
        Ok(())
    }
}

//! Unary, binary, and `if` frames: operand resumption, lazy boolean
//! operands, and the branch joins that follow them.

use crate::ast::{BinaryOp, Expr, ExprKind, Type, UnaryOp};
use crate::diagnostic::Diagnostic;
use crate::source_verify::IterativeVerifier;
use crate::source_verify::binding::{Availability, Binding, CheckedValue};
use crate::source_verify::diagnostics::{
    error, reject_aggregate_equality, reject_native_unit_value,
};
use crate::source_verify::hints;
use crate::source_verify::loans::join_conditional;
use crate::source_verify::place::{join_definitely_partial, join_moved_places};
use crate::source_verify::private_names::type_name;
use crate::source_verify::scope::{VerifierFrame, VerifierScope};
use std::collections::HashMap;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    pub(super) fn frame_resume_unary(
        &mut self,
        expression: &'p Expr,
        operand: &'p Expr,
        op: UnaryOp,
    ) -> Result<(), Diagnostic> {
        #[cfg(test)]
        if self.recovery_legacy {
            return self.recovery_old_frame_resume_unary(expression, operand, op);
        }

        let Some(actual) = self.values.pop().flatten() else {
            self.values.push(None);
            return Ok(());
        };
        let numeric = matches!(op, UnaryOp::Neg)
            .then(|| actual.ty.clone())
            .filter(|ty| matches!(ty, Type::I64 | Type::I32 | Type::F32 | Type::F64));
        let expected = match (&op, &numeric) {
            (UnaryOp::Neg, Some(ty)) => ty.clone(),
            (UnaryOp::Neg, None) => Type::I64,
            (UnaryOp::Not, _) => Type::Bool,
        };
        let mismatched = !actual.native_unit && actual.ty != expected;
        if mismatched
            && !self
                .recovery
                .explains_acceptance(operand, |declared| match op {
                    UnaryOp::Neg => {
                        matches!(declared, Type::I64 | Type::I32 | Type::F32 | Type::F64)
                    }
                    UnaryOp::Not => *declared == Type::Bool,
                })
        {
            self.diagnostics.push(error(
                self.program,
                "SPX-T206",
                format!("unary operator expects {expected}, received {}", actual.ty),
                expression.span,
            ));
        }
        reject_native_unit_value(self.program, operand, &actual, self.diagnostics);
        self.values
            .push((!mismatched).then(|| CheckedValue::value(expected)));
        Ok(())
    }

    pub(super) fn frame_resume_binary_left(
        &mut self,
        expression: &'p Expr,
        op: BinaryOp,
        right: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let left_value = self.values.pop().unwrap_or(None);
        let lazy = matches!(op, BinaryOp::And | BinaryOp::Or);
        let baseline_names = if lazy {
            self.scopes[scope]
                .bindings
                .keys()
                .cloned()
                .collect::<Vec<_>>()
        } else {
            Vec::new()
        };
        let evaluated_scope = if lazy {
            let index = self.scopes.len();
            self.recovery.fork(Some(scope), index);
            self.scopes.push(VerifierScope {
                bindings: self.scopes[scope].bindings.clone(),
                local_borrow_count: self.scopes[scope].local_borrow_count,
            });
            index
        } else {
            scope
        };
        let left = match &expression.kind {
            ExprKind::Binary { left, .. } => left.as_ref(),
            _ => unreachable!(),
        };
        self.frames.push(VerifierFrame::ResumeBinaryRight {
            expression,
            op,
            left,
            left_value,
            scope,
            evaluated_scope,
            baseline_names,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: right,
            scope: evaluated_scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_binary_right(
        &mut self,
        expression: &'p Expr,
        op: BinaryOp,
        left: &'p Expr,
        left_value: Option<CheckedValue>,
        scope: usize,
        evaluated_scope: usize,
        baseline_names: Vec<String>,
    ) -> Result<(), Diagnostic> {
        #[cfg(test)]
        if self.recovery_legacy {
            return self.recovery_old_frame_resume_binary_right(
                expression,
                op,
                left,
                left_value,
                scope,
                evaluated_scope,
                baseline_names,
            );
        }

        let right_value = self.values.pop().unwrap_or(None);
        if evaluated_scope != scope {
            if evaluated_scope + 1 != self.scopes.len() {
                return Err(Diagnostic::io(
                    "SPX-H006",
                    "lazy verifier scope is not the active child",
                ));
            }
            let evaluated = self
                .scopes
                .pop()
                .expect("active lazy scope index checked above")
                .bindings;
            join_conditional(
                &mut self.scopes[scope].bindings,
                &evaluated,
                &baseline_names,
            );
        }
        if let Some(value) = &left_value {
            reject_native_unit_value(self.program, left, value, self.diagnostics);
        }
        let right = match &expression.kind {
            ExprKind::Binary { right, .. } => right.as_ref(),
            _ => unreachable!(),
        };
        if let Some(value) = &right_value {
            reject_native_unit_value(self.program, right, value, self.diagnostics);
        }
        let native_unit = left_value.as_ref().is_some_and(|value| value.native_unit)
            || right_value.as_ref().is_some_and(|value| value.native_unit);
        let left_ordered = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| {
                matches!(
                    ty,
                    Type::I64
                        | Type::I32
                        | Type::Char
                        | Type::U8
                        | Type::Usize
                        | Type::F32
                        | Type::F64
                        | Type::String
                )
            });
        let left_narrow = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::U8));
        let left_usize = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::Usize));
        let left_numeric = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::F32 | Type::F64));
        let left_integer = left_value
            .as_ref()
            .map(|value| value.ty.clone())
            .filter(|ty| matches!(ty, Type::I32));
        if !native_unit && matches!(op, BinaryOp::Rem) && left_numeric.is_some() {
            self.diagnostics.push(error(
                self.program,
                "SPX-T208",
                format!("operator `{}` expects i64 operands", op.text()),
                expression.span,
            ));
        }
        let string_operands = left_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::String)
            || right_value
                .as_ref()
                .is_some_and(|value| value.ty == Type::String);
        if !native_unit
            && !matches!(
                op,
                BinaryOp::Eq
                    | BinaryOp::Ne
                    | BinaryOp::Lt
                    | BinaryOp::Le
                    | BinaryOp::Gt
                    | BinaryOp::Ge
            )
            && string_operands
        {
            let independent_string = |operand: &Expr, value: &Option<CheckedValue>| {
                value.as_ref().is_some_and(|value| value.ty == Type::String)
                    && !self
                        .recovery
                        .explains_acceptance(operand, |declared| match op {
                            BinaryOp::And | BinaryOp::Or => *declared == Type::Bool,
                            BinaryOp::Rem => {
                                matches!(declared, Type::I64 | Type::I32 | Type::U8 | Type::Usize)
                            }
                            _ => matches!(
                                declared,
                                Type::I64
                                    | Type::I32
                                    | Type::F32
                                    | Type::F64
                                    | Type::U8
                                    | Type::Usize
                            ),
                        })
            };
            if independent_string(left, &left_value) || independent_string(right, &right_value) {
                self.diagnostics.push(
                    error(
                        self.program,
                        "SPX-T250",
                        format!("operator `{}` does not support string operands", op.text()),
                        expression.span,
                    )
                    .with_help(crate::source_verify::hints::STRING_OPERATOR_HELP),
                );
            }
            if matches!(
                op,
                BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Rem
            ) {
                self.values.push(None);
                return Ok(());
            }
        }
        let (expected, output) = match op {
            BinaryOp::Add | BinaryOp::Sub | BinaryOp::Mul | BinaryOp::Div | BinaryOp::Rem => {
                let expected = left_numeric
                    .clone()
                    .or(left_integer)
                    .or(left_narrow)
                    .or(left_usize)
                    .unwrap_or(Type::I64);
                (expected.clone(), expected)
            }
            BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge => {
                let expected = left_ordered.unwrap_or(Type::I64);
                (expected, Type::Bool)
            }
            BinaryOp::And | BinaryOp::Or => (Type::Bool, Type::Bool),
            BinaryOp::Eq | BinaryOp::Ne => {
                if let Some(value) = &left_value {
                    reject_aggregate_equality(
                        self.program,
                        self.types,
                        expression,
                        value,
                        self.diagnostics,
                    );
                }
                if !native_unit
                    && left_value.is_some()
                    && right_value.is_some()
                    && left_value.as_ref().map(|value| &value.ty)
                        != right_value.as_ref().map(|value| &value.ty)
                    && !right_value
                        .as_ref()
                        .is_some_and(|value| self.recovery.explains(left, &value.ty))
                    && !left_value
                        .as_ref()
                        .is_some_and(|value| self.recovery.explains(right, &value.ty))
                {
                    self.diagnostics.push(hints::with_optional_help(
                        error(
                            self.program,
                            "SPX-T207",
                            "equality operands must have the same type",
                            expression.span,
                        ),
                        hints::equality_types_help(
                            left_value.as_ref().map(|value| &value.ty),
                            right_value.as_ref().map(|value| &value.ty),
                            left,
                            right,
                        ),
                    ));
                }
                self.values.push(Some(CheckedValue::value(Type::Bool)));
                return Ok(());
            }
        };
        if !native_unit
            && (!string_operands
                || matches!(
                    op,
                    BinaryOp::Lt | BinaryOp::Le | BinaryOp::Gt | BinaryOp::Ge
                ))
            && (left_value.as_ref().is_some_and(|value| {
                value.ty != expected && !self.recovery.explains(left, &expected)
            }) || right_value.as_ref().is_some_and(|value| {
                value.ty != expected && !self.recovery.explains(right, &expected)
            }))
        {
            self.diagnostics.push(hints::with_optional_help(
                error(
                    self.program,
                    "SPX-T208",
                    format!("operator `{}` expects {expected} operands", op.text()),
                    expression.span,
                ),
                hints::literal_suffix_help(&expected, left, right),
            ));
        }
        self.values.push(Some(CheckedValue::value(output)));
        Ok(())
    }

    pub(super) fn frame_resume_if_condition(
        &mut self,
        expression: &'p Expr,
        then_branch: &'p Expr,
        else_branch: &'p Expr,
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let condition_value = self.values.pop().unwrap_or(None);
        let condition = match &expression.kind {
            ExprKind::If { condition, .. } => condition.as_ref(),
            _ => unreachable!(),
        };
        if let Some(value) = condition_value {
            if value.native_unit {
                reject_native_unit_value(self.program, condition, &value, self.diagnostics);
            } else if value.ty != Type::Bool && !self.recovery.explains(condition, &Type::Bool) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T210",
                    "`if` condition must be bool",
                    condition.span,
                ));
            }
        }
        // Empty blocks containing only a scalar literal cannot inspect or
        // mutate any binding. Check both literal values normally, but avoid
        // copying and joining the complete environment for this identity case.
        let literal_tail = |branch: &'p Expr| match &branch.kind {
            ExprKind::Block { statements, tail }
                if statements.is_empty()
                    && matches!(tail.kind, ExprKind::Int(_) | ExprKind::Bool(_)) =>
            {
                Some(tail.as_ref())
            }
            _ => None,
        };
        if let (Some(then_tail), Some(else_tail)) =
            (literal_tail(then_branch), literal_tail(else_branch))
        {
            self.frames.push(VerifierFrame::ResumeLiteralIf {
                expression,
                then_branch,
                else_branch,
            });
            self.frames.push(VerifierFrame::Enter {
                expression: else_tail,
                scope,
            });
            self.frames.push(VerifierFrame::Enter {
                expression: then_tail,
                scope,
            });
            return Ok(());
        }
        let baseline_names = self.scopes[scope]
            .bindings
            .keys()
            .cloned()
            .collect::<Vec<_>>();
        let then_scope = self.scopes.len();
        self.recovery.fork(Some(scope), then_scope);
        self.scopes.push(VerifierScope {
            bindings: self.scopes[scope].bindings.clone(),
            local_borrow_count: self.scopes[scope].local_borrow_count,
        });
        self.frames.push(VerifierFrame::ResumeIfThen {
            expression,
            else_branch,
            scope,
            then_scope,
            baseline_names,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: then_branch,
            scope: then_scope,
        });
        Ok(())
    }

    pub(super) fn frame_resume_if_then(
        &mut self,
        expression: &'p Expr,
        else_branch: &'p Expr,
        scope: usize,
        then_scope: usize,
        baseline_names: Vec<String>,
    ) -> Result<(), Diagnostic> {
        if then_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "then verifier scope is not the active child",
            ));
        }
        let then_value = self.values.pop().unwrap_or(None);
        let then_bindings = self
            .scopes
            .pop()
            .expect("active then scope index checked above")
            .bindings;
        let else_scope = self.scopes.len();
        self.recovery.fork(Some(scope), else_scope);
        self.scopes.push(VerifierScope {
            bindings: self.scopes[scope].bindings.clone(),
            local_borrow_count: self.scopes[scope].local_borrow_count,
        });
        let then_branch = match &expression.kind {
            ExprKind::If { then_branch, .. } => then_branch.as_ref(),
            _ => unreachable!(),
        };
        self.frames.push(VerifierFrame::ResumeIfElse {
            expression,
            then_branch,
            else_branch,
            scope,
            else_scope,
            baseline_names,
            then_value,
            then_bindings,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: else_branch,
            scope: else_scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_if_else(
        &mut self,
        expression: &'p Expr,
        then_branch: &'p Expr,
        else_branch: &'p Expr,
        scope: usize,
        else_scope: usize,
        baseline_names: Vec<String>,
        then_value: Option<CheckedValue>,
        then_bindings: HashMap<String, Binding>,
    ) -> Result<(), Diagnostic> {
        if else_scope + 1 != self.scopes.len() {
            return Err(Diagnostic::io(
                "SPX-H006",
                "else verifier scope is not the active child",
            ));
        }
        let else_value = self.values.pop().unwrap_or(None);
        let else_bindings = self
            .scopes
            .pop()
            .expect("active else scope index checked above")
            .bindings;
        let then_exits = then_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(then_branch);
        let else_exits = else_value
            .as_ref()
            .is_some_and(|value| value.ty == Type::Never)
            && crate::ast::returns_only(else_branch);
        for name in &baseline_names {
            if let Some(binding) = self.scopes[scope].bindings.get_mut(name) {
                if then_exits != else_exits {
                    let normal = if then_exits {
                        &else_bindings
                    } else {
                        &then_bindings
                    };
                    if let Some(state) = normal.get(name) {
                        *binding = state.clone();
                    }
                    continue;
                }
                let then_state = then_bindings
                    .get(name)
                    .map_or(Availability::Available, |value| value.availability);
                let else_state = else_bindings
                    .get(name)
                    .map_or(Availability::Available, |value| value.availability);
                binding.availability = then_state.join(else_state);
                if let (Some(then_binding), Some(else_binding)) =
                    (then_bindings.get(name), else_bindings.get(name))
                {
                    binding.active_loans = then_binding
                        .active_loans
                        .union(&else_binding.active_loans)
                        .cloned()
                        .collect();
                    binding.moved_places = join_moved_places(then_binding, else_binding);
                    binding.definitely_partial =
                        join_definitely_partial(then_binding, else_binding);
                }
            }
        }
        self.finish_if_values(expression, then_branch, else_branch, then_value, else_value);
        Ok(())
    }

    pub(super) fn finish_if_values(
        &mut self,
        expression: &Expr,
        then_branch: &Expr,
        else_branch: &Expr,
        then_value: Option<CheckedValue>,
        else_value: Option<CheckedValue>,
    ) {
        let output = match (then_value, else_value) {
            (Some(then_value), Some(else_value)) if then_value.ty == Type::Never => {
                Some(else_value)
            }
            (Some(then_value), Some(else_value)) if else_value.ty == Type::Never => {
                Some(then_value)
            }
            (Some(then_value), Some(else_value)) => {
                if then_value.native_unit || else_value.native_unit {
                    reject_native_unit_value(
                        self.program,
                        then_branch,
                        &then_value,
                        self.diagnostics,
                    );
                    reject_native_unit_value(
                        self.program,
                        else_branch,
                        &else_value,
                        self.diagnostics,
                    );
                } else if then_value.ty != else_value.ty {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-T211",
                        format!(
                            "`if` branches return different types: {} and {}",
                            type_name(self.program, self.types, &then_value.ty),
                            type_name(self.program, self.types, &else_value.ty)
                        ),
                        expression.span,
                    ));
                }
                if self.types.needs_drop(&then_value.ty) && then_value.mode != else_value.mode {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O106",
                        "`if` branches must produce the same resource ownership mode",
                        expression.span,
                    ));
                }
                Some(then_value)
            }
            _ => None,
        };
        self.values.push(output);
    }
}

//! Record, variant, and record-update construction frames: per-field
//! preparation and resumption.

use crate::ast::{
    Expr, FieldDeclaration, ParamMode, Type, TypeDeclaration, VariantCaseDeclaration,
};
use crate::diagnostic::Diagnostic;
use crate::source_verify::IterativeVerifier;
use crate::source_verify::binding::CheckedValue;
use crate::source_verify::diagnostics::{error, reject_native_unit_value};
use crate::source_verify::loans::mark_value_sources_moved;
use crate::source_verify::place::source_place;
use crate::source_verify::scope::VerifierFrame;
use crate::source_verify::type_table::{TypeTable, effective_record_fields};
use std::collections::HashSet;

impl<'a, 'p> IterativeVerifier<'a, 'p> {
    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_prepare_record_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: Option<&'p [FieldDeclaration]>,
        scope: usize,
        index: usize,
        mut supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        #[cfg(test)]
        if self.recovery_legacy {
            return self.recovery_old_frame_prepare_record_field(
                expression,
                type_name,
                type_arguments,
                fields,
                declared_fields,
                scope,
                index,
                supplied,
            );
        }
        let field = &fields[index];
        let declared = self
            .types
            .declared_field(type_name, &field.name)
            .or_else(|| {
                declared_fields.and_then(|declared| {
                    declared
                        .iter()
                        .find(|candidate| candidate.name == field.name)
                })
            });
        let duplicate = !supplied.insert(field.name.as_str());
        if duplicate || (declared.is_none() && declared_fields.is_some()) {
            self.diagnostics.push(error(
                self.program,
                "SPX-T212",
                format!(
                    "unknown or duplicate field `{}` in `{type_name}` construction",
                    field.name
                ),
                field.span,
            ));
        }
        self.frames.push(VerifierFrame::ResumeRecordField {
            expression,
            type_name,
            type_arguments,
            fields,
            declared_fields,
            scope,
            index,
            supplied,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: &field.value,
            scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_record_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: Option<&'p [FieldDeclaration]>,
        scope: usize,
        index: usize,
        supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let field = &fields[index];
        let declared = self
            .types
            .declared_field(type_name, &field.name)
            .or_else(|| {
                declared_fields.and_then(|declared| {
                    declared
                        .iter()
                        .find(|candidate| candidate.name == field.name)
                })
            });
        if let (Some(declared), Some(actual)) = (declared, actual) {
            reject_native_unit_value(self.program, &field.value, &actual, self.diagnostics);
            let expected = self
                .types
                .declaration(type_name)
                .and_then(|declaration| {
                    TypeTable::substitute_variant_type(declaration, type_arguments, &declared.ty)
                })
                .unwrap_or_else(|| declared.ty.clone());
            if actual.ty != expected && !self.recovery.explains(&field.value, &expected) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T215",
                    format!(
                        "field `{}.{}` expects {}, received {}",
                        type_name, field.name, expected, actual.ty
                    ),
                    field.value.span,
                ));
            }
            if self.types.needs_drop(&expected) && actual.mode == ParamMode::Own {
                if self.allow_moves {
                    mark_value_sources_moved(
                        self.program,
                        &field.value,
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.diagnostics,
                    );
                } else {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O105",
                        "contract expression cannot transfer an owned record field",
                        field.value.span,
                    ));
                }
            } else if self.types.needs_drop(&expected)
                && matches!(actual.mode, ParamMode::Borrow | ParamMode::Shared)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot move an owned field through a borrowed or shared record",
                    field.value.span,
                ));
            }
        }
        let next = index + 1;
        if fields.get(next).is_some() {
            self.frames.push(VerifierFrame::PrepareRecordField {
                expression,
                type_name,
                type_arguments,
                fields,
                declared_fields,
                scope,
                index: next,
                supplied,
            });
        } else {
            if let Some(declared_fields) = declared_fields {
                for field in declared_fields {
                    if !supplied.contains(field.name.as_str()) {
                        self.diagnostics.push(error(
                            self.program,
                            "SPX-T213",
                            format!(
                                "record `{type_name}` construction is missing field `{}`",
                                field.name
                            ),
                            expression.span,
                        ));
                    }
                }
                let instance = Type::Named {
                    name: type_name.to_owned(),
                    arguments: type_arguments.to_vec(),
                };
                crate::source_verify::declared_type::string_record::reject(
                    self.program,
                    &instance,
                    "constructed",
                    expression.span,
                    self.types,
                    self.diagnostics,
                );
                self.values.push(Some(CheckedValue::returned(
                    instance.clone(),
                    self.types.needs_drop(&instance),
                )));
            } else {
                self.values.push(None);
            }
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_prepare_variant_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        case_name: &'p str,
        fields: &'p [crate::ast::FieldInitializer],
        declaration: Option<&'p TypeDeclaration>,
        case: Option<&'p VariantCaseDeclaration>,
        scope: usize,
        index: usize,
        mut supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let field = &fields[index];
        let declared = case.and_then(|case| {
            case.fields
                .iter()
                .find(|candidate| candidate.name == field.name)
        });
        if !supplied.insert(field.name.as_str()) || (case.is_some() && declared.is_none()) {
            self.diagnostics.push(error(self.program, "SPX-T212", format!("unknown or duplicate payload field `{}` in `{type_name}::{case_name}` construction", field.name), field.span));
        }
        self.frames.push(VerifierFrame::ResumeVariantField {
            expression,
            type_name,
            type_arguments,
            case_name,
            fields,
            declaration,
            case,
            scope,
            index,
            supplied,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: &field.value,
            scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_variant_field(
        &mut self,
        expression: &'p Expr,
        type_name: &'p str,
        type_arguments: &'p [Type],
        case_name: &'p str,
        fields: &'p [crate::ast::FieldInitializer],
        declaration: Option<&'p TypeDeclaration>,
        case: Option<&'p VariantCaseDeclaration>,
        scope: usize,
        index: usize,
        supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let field = &fields[index];
        let declared = case.and_then(|case| {
            case.fields
                .iter()
                .find(|candidate| candidate.name == field.name)
        });
        if let (Some(declaration), Some(declared), Some(actual)) = (declaration, declared, actual) {
            reject_native_unit_value(self.program, &field.value, &actual, self.diagnostics);
            let expected =
                TypeTable::substitute_variant_type(declaration, type_arguments, &declared.ty)
                    .unwrap_or_else(|| declared.ty.clone());
            if actual.ty != expected && !self.recovery.explains(&field.value, &expected) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T215",
                    format!(
                        "payload `{}::{}.{}` expects {}, received {}",
                        type_name, case_name, field.name, expected, actual.ty
                    ),
                    field.value.span,
                ));
            }
            if self.types.needs_drop(&expected) && actual.mode == ParamMode::Own {
                if self.allow_moves {
                    mark_value_sources_moved(
                        self.program,
                        &field.value,
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.diagnostics,
                    );
                } else {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O105",
                        "contract expression cannot transfer an owned variant payload",
                        field.value.span,
                    ));
                }
            } else if self.types.needs_drop(&expected)
                && matches!(actual.mode, ParamMode::Borrow | ParamMode::Shared)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot move an owned variant payload through a borrowed or shared value",
                    field.value.span,
                ));
            }
        }
        let next = index + 1;
        if fields.get(next).is_some() {
            self.frames.push(VerifierFrame::PrepareVariantField {
                expression,
                type_name,
                type_arguments,
                case_name,
                fields,
                declaration,
                case,
                scope,
                index: next,
                supplied,
            });
        } else {
            if let Some(case) = case {
                for field in &case.fields {
                    if !supplied.contains(field.name.as_str()) {
                        self.diagnostics.push(error(self.program, "SPX-T213", format!("variant construction `{type_name}::{case_name}` is missing payload field `{}`", field.name), expression.span));
                    }
                }
                let instance = Type::Named {
                    name: type_name.to_owned(),
                    arguments: type_arguments.to_vec(),
                };
                self.values.push(Some(CheckedValue::returned(
                    instance.clone(),
                    self.types.needs_drop(&instance),
                )));
            } else if declaration.is_some() {
                let instance = Type::Named {
                    name: type_name.to_owned(),
                    arguments: type_arguments.to_vec(),
                };
                self.values.push(Some(CheckedValue::returned(
                    instance.clone(),
                    self.types.needs_drop(&instance),
                )));
            } else {
                self.values.push(None);
            }
        }
        Ok(())
    }

    pub(super) fn frame_resume_update_base(
        &mut self,
        expression: &'p Expr,
        base: &'p Expr,
        fields: &'p [crate::ast::FieldInitializer],
        scope: usize,
    ) -> Result<(), Diagnostic> {
        let Some(base_value) = self.values.pop().flatten() else {
            self.values.push(None);
            return Ok(());
        };
        reject_native_unit_value(self.program, base, &base_value, self.diagnostics);
        if crate::source_verify::declared_type::collection_record::admitted(
            &base_value.ty,
            self.types,
        ) {
            self.diagnostics.push(error(
                self.program,
                "SPX-T268",
                "Vec-bearing record update is outside the nested collection-record profile",
                expression.span,
            ));
            self.values.push(None);
            return Ok(());
        }
        let Some(declared_fields) = effective_record_fields(self.types, &base_value.ty) else {
            self.diagnostics.push(error(
                self.program,
                "SPX-T215",
                format!(
                    "record update requires a record base, received {}",
                    base_value.ty
                ),
                base.span,
            ));
            self.values.push(None);
            return Ok(());
        };
        let nested_update = (self.types.is_nested_owned_byte_record(&base_value.ty)
            && !self.types.is_flat_owned_byte_record(&base_value.ty))
            || crate::source_verify::declared_type::string_record::admitted(
                &base_value.ty,
                self.types,
            );
        if nested_update
            && source_place(base, &self.scopes[scope].bindings, self.types)
                .is_none_or(|place| !place.projections.is_empty())
        {
            self.diagnostics.push(error(
                self.program,
                "SPX-O117",
                "nested owned-record update requires an exact named owned base place",
                expression.span,
            ));
        }
        if self.types.needs_drop(&base_value.ty) {
            match base_value.mode {
                ParamMode::Own if self.allow_moves => mark_value_sources_moved(
                    self.program,
                    base,
                    &mut self.scopes[scope].bindings,
                    self.types,
                    self.diagnostics,
                ),
                ParamMode::Own => self.diagnostics.push(error(
                    self.program,
                    "SPX-O105",
                    "contract expression cannot transfer an owned record update base",
                    base.span,
                )),
                ParamMode::Borrow | ParamMode::Shared => self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot update an owned record through a borrowed or shared base",
                    base.span,
                )),
                ParamMode::Value => {}
            }
        }
        if !fields.is_empty() {
            self.frames.push(VerifierFrame::PrepareUpdateField {
                expression,
                base_type: base_value.ty,
                fields,
                declared_fields,
                scope,
                index: 0,
                supplied: HashSet::new(),
            });
        } else {
            self.values.push(Some(CheckedValue::returned(
                base_value.ty.clone(),
                self.types.needs_drop(&base_value.ty),
            )));
        }
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_prepare_update_field(
        &mut self,
        expression: &'p Expr,
        base_type: Type,
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: &'p [FieldDeclaration],
        scope: usize,
        index: usize,
        mut supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let field = &fields[index];
        let declared = declared_fields
            .iter()
            .find(|candidate| candidate.name == field.name);
        if !supplied.insert(field.name.as_str()) || declared.is_none() {
            self.diagnostics.push(error(
                self.program,
                "SPX-T212",
                format!(
                    "unknown or duplicate field `{}` in `{}` update",
                    field.name, base_type
                ),
                field.span,
            ));
        }
        self.frames.push(VerifierFrame::ResumeUpdateField {
            expression,
            base_type,
            fields,
            declared_fields,
            scope,
            index,
            supplied,
        });
        self.frames.push(VerifierFrame::Enter {
            expression: &field.value,
            scope,
        });
        Ok(())
    }

    #[allow(clippy::too_many_arguments)]
    pub(super) fn frame_resume_update_field(
        &mut self,
        expression: &'p Expr,
        base_type: Type,
        fields: &'p [crate::ast::FieldInitializer],
        declared_fields: &'p [FieldDeclaration],
        scope: usize,
        index: usize,
        supplied: HashSet<&'p str>,
    ) -> Result<(), Diagnostic> {
        let actual = self.values.pop().unwrap_or(None);
        let field = &fields[index];
        let declared = declared_fields
            .iter()
            .find(|candidate| candidate.name == field.name);
        if let (Some(declared), Some(actual)) = (declared, actual) {
            reject_native_unit_value(self.program, &field.value, &actual, self.diagnostics);
            let expected = self
                .types
                .record_field_type(&base_type, declared)
                .unwrap_or_else(|| declared.ty.clone());
            if actual.ty != expected && !self.recovery.explains(&field.value, &expected) {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-T215",
                    format!(
                        "field `{}.{}` expects {}, received {}",
                        base_type, field.name, expected, actual.ty
                    ),
                    field.value.span,
                ));
            }
            if self.types.needs_drop(&expected) && actual.mode == ParamMode::Own {
                if self.allow_moves {
                    mark_value_sources_moved(
                        self.program,
                        &field.value,
                        &mut self.scopes[scope].bindings,
                        self.types,
                        self.diagnostics,
                    );
                } else {
                    self.diagnostics.push(error(
                        self.program,
                        "SPX-O105",
                        "contract expression cannot transfer an owned record replacement",
                        field.value.span,
                    ));
                }
            } else if self.types.needs_drop(&expected)
                && matches!(actual.mode, ParamMode::Borrow | ParamMode::Shared)
            {
                self.diagnostics.push(error(
                    self.program,
                    "SPX-O108",
                    "cannot move an owned replacement through a borrowed or shared value",
                    field.value.span,
                ));
            }
        }
        let next = index + 1;
        if fields.get(next).is_some() {
            self.frames.push(VerifierFrame::PrepareUpdateField {
                expression,
                base_type,
                fields,
                declared_fields,
                scope,
                index: next,
                supplied,
            });
        } else {
            self.values.push(Some(CheckedValue::returned(
                base_type.clone(),
                self.types.needs_drop(&base_type),
            )));
        }
        Ok(())
    }
}

//! Lexical missing-declaration recovery and separate annotation refusal views.
//!
//! Names borrow immutable authored source. This directory never supplies a type,
//! binding, capture, ownership state, or backend admission. Ordinary source
//! verifier storage has no physical payer; these error-only allocations remain
//! ordinary storage, not paid replay authority.

use std::collections::BTreeMap;

use crate::ast::{Expr, ExprKind, Function, Type};
use crate::diagnostic::Diagnostic;

#[derive(Default)]
struct Scope<'p> {
    parent: Option<usize>,
    names: BTreeMap<&'p str, (usize, bool, Option<&'p Type>)>,
}

/// A declaration refusal explains an expected-type failure; it never replaces
/// the independently checked value or any binding/ownership metadata.
#[derive(Clone, Copy)]
pub(super) struct RefusalView<'p> {
    pub(super) origin: usize,
    pub(super) declared: &'p Type,
}

#[derive(Clone, Copy)]
pub(super) struct Checkpoint {
    pub(super) diagnostics: usize,
    reads: usize,
}

#[derive(Default)]
pub(super) struct Recovery<'p> {
    scopes: Vec<Scope<'p>>,
    last_read: Option<usize>,
    reads: usize,
    // Opaque borrowed expression identities are invocation-local lookup keys.
    // They are never dereferenced, iterated to select diagnostics, or emitted.
    // Only reads of real annotation-refused bindings acquire entries.
    expressions: BTreeMap<*const Expr, RefusalView<'p>>,
    #[cfg(test)]
    pub(super) visited: usize,
}

impl<'p> Recovery<'p> {
    /// Recheck each affected declaration once in this invocation, only after an
    /// existing unknown-type refusal. Equal byte spans alone are insufficient
    /// for externally constructed source trees or duplicate parameters.
    pub(super) fn signature(
        program: &'p dyn crate::ast::program_source::ProgramSource,
        current: &'p Function,
        variables: &std::collections::HashMap<String, super::binding::Binding>,
        types: &super::type_table::TypeTable<'_>,
        diagnostics: &[Diagnostic],
    ) -> Self {
        let mut recovery = Self::default();
        if !diagnostics
            .iter()
            .any(|diagnostic| diagnostic.code == "SPX-T001")
        {
            return recovery;
        }
        let mut parameters = None;
        let mut scratch = Vec::new();
        for parameter in &current.params {
            if types.needs_drop(&parameter.ty)
                || variables.get(&parameter.name).is_none_or(|binding| {
                    binding.ty != parameter.ty || binding.mode != parameter.mode
                })
                || !diagnostics.iter().any(|diagnostic| {
                    diagnostic.code == "SPX-T001" && diagnostic.span == Some(parameter.span)
                })
            {
                continue;
            }
            let parameters = parameters.get_or_insert_with(|| {
                current
                    .type_parameters
                    .iter()
                    .map(|parameter| parameter.name.as_str())
                    .collect()
            });
            scratch.clear();
            super::declared_type::check_declared_type(
                program,
                &parameter.ty,
                parameter.span,
                types,
                parameters,
                &mut scratch,
            );
            if let Some(origin) = scratch
                .iter()
                .filter(|refusal| refusal.code == "SPX-T001")
                .find_map(|refusal| {
                    diagnostics.iter().position(|original| {
                        original.code == refusal.code
                            && original.severity == refusal.severity
                            && original.message == refusal.message
                            && original.path == refusal.path
                            && original.span == refusal.span
                            && original.help == refusal.help
                    })
                })
            {
                recovery.ensure(0);
                recovery.scopes[0]
                    .names
                    .insert(parameter.name.as_str(), (origin, true, None));
            }
        }
        recovery
    }

    pub(super) fn clear(&mut self, scope: usize, name: &str) {
        if let Some(row) = self.scopes.get_mut(scope) {
            row.names.remove(name);
        }
    }

    /// Scope ordinals are reused after a branch or block ends. Reset the row
    /// before entering that ordinal; a former sibling must never be an ancestor.
    /// Before the first refused declaration there are no inherited facts, so
    /// successful programs do not acquire a directory merely to fork scopes.
    pub(super) fn fork(&mut self, parent: Option<usize>, child: usize) {
        if self.scopes.is_empty() {
            return;
        }
        self.ensure(child);
        self.scopes[child] = Scope {
            parent,
            names: BTreeMap::new(),
        };
    }

    fn ensure(&mut self, scope: usize) {
        if self.scopes.len() <= scope {
            self.scopes.resize_with(scope + 1, Scope::default);
        }
    }

    /// Only an absent checked binding/function reaches this lookup. Existing
    /// availability, loan, move, and function-value diagnostics run first.
    pub(super) fn reads_refused(&mut self, scope: usize, name: &str) -> bool {
        self.read(scope, name, false).is_some()
    }

    #[cfg(test)]
    pub(super) fn reads_known_refused(&mut self, scope: usize, name: &str) -> bool {
        self.read(scope, name, true).is_some()
    }

    /// Keep the full actual value for annotation refusals. Unknown signature
    /// types keep their existing narrower inference behavior in this batch.
    pub(super) fn reads_value(&mut self, scope: usize, name: &str, expression: &Expr) -> bool {
        match self.read(scope, name, true) {
            Some((origin, Some(declared))) => {
                self.expressions.insert(
                    std::ptr::from_ref(expression),
                    RefusalView { origin, declared },
                );
                false
            }
            Some((_, None)) => true,
            None => false,
        }
    }

    pub(super) fn begin(&mut self, expression: &Expr) {
        self.expressions.remove(&std::ptr::from_ref(expression));
    }

    /// Blocks return their checked tail. Follow only that transparent chain,
    /// never statements or sibling arms, and never rescan a whole function.
    pub(super) fn view(&self, mut expression: &Expr) -> Option<RefusalView<'p>> {
        loop {
            if let Some(view) = self.expressions.get(&std::ptr::from_ref(expression)) {
                return Some(*view);
            }
            let ExprKind::Block { tail, .. } = &expression.kind else {
                return None;
            };
            expression = tail;
        }
    }

    pub(super) fn explains(&self, expression: &Expr, expected: &Type) -> bool {
        self.view(expression)
            .is_some_and(|view| view.declared == expected)
    }

    pub(super) fn explains_acceptance(
        &self,
        expression: &Expr,
        accepts: impl FnOnce(&Type) -> bool,
    ) -> bool {
        self.view(expression)
            .is_some_and(|view| accepts(view.declared))
    }

    pub(super) fn inherit_binding(&mut self, scope: usize, name: &'p str, value: &Expr) {
        if let Some(view) = self.view(value) {
            self.refused_annotation(scope, name, view.declared, view.origin);
        }
    }

    fn read(
        &mut self,
        mut scope: usize,
        name: &str,
        known: bool,
    ) -> Option<(usize, Option<&'p Type>)> {
        while let Some(row) = self.scopes.get(scope) {
            #[cfg(test)]
            {
                self.visited += 1;
            }
            if let Some(&(origin, declaration_known, declared)) = row.names.get(name) {
                // A missing declaration never outranks a real function value
                // or checked binding. Known markers are inference-only.
                if declaration_known != known {
                    return None;
                }
                self.last_read = Some(origin);
                self.reads += 1;
                return Some((origin, declared));
            }
            let Some(parent) = row.parent else {
                break;
            };
            scope = parent;
        }
        None
    }

    pub(super) fn checkpoint(&self, diagnostics: &[Diagnostic]) -> Checkpoint {
        Checkpoint {
            diagnostics: diagnostics.len(),
            reads: self.reads,
        }
    }

    /// Publish only after the complete initializer. A continuation captures the
    /// diagnostic/read frontier before evaluation, including nested blocks;
    /// source spans or old unrelated diagnostics cannot manufacture this fact.
    pub(super) fn refused_let(
        &mut self,
        scope: usize,
        name: &'p str,
        checkpoint: Checkpoint,
        diagnostics: &[Diagnostic],
    ) {
        self.publish(scope, name, checkpoint, diagnostics, false);
    }

    pub(super) fn refused_annotation(
        &mut self,
        scope: usize,
        name: &'p str,
        declared: &'p Type,
        origin: usize,
    ) {
        self.ensure(scope);
        self.scopes[scope]
            .names
            .insert(name, (origin, true, Some(declared)));
    }

    fn publish(
        &mut self,
        scope: usize,
        name: &'p str,
        checkpoint: Checkpoint,
        diagnostics: &[Diagnostic],
        known: bool,
    ) {
        let origin = diagnostics
            .iter()
            .enumerate()
            .skip(checkpoint.diagnostics)
            .find(|(_, diagnostic)| diagnostic.severity.is_error())
            .map(|(index, _)| index)
            .or_else(|| {
                (self.reads > checkpoint.reads)
                    .then_some(self.last_read)
                    .flatten()
            });
        if let Some(origin) = origin {
            self.ensure(scope);
            self.scopes[scope].names.insert(name, (origin, known, None));
        }
    }
}

//! Complete original iterative receiver against intentional recovery deltas,
//! with the unchanged recursive receiver retained independently.
use super::binding::{Availability, Binding};
use super::check_expr;
use super::recovery::Recovery;
use super::type_table::TypeTable;
#[path = "recovery_tests/boundaries.rs"]
mod boundaries;
#[path = "recovery_tests/proposal_corpus.rs"]
mod proposal_corpus;
#[path = "recovery_tests/refusal_dependency.rs"]
mod refusal_dependency;
use crate::ast::{ParamMode, Span, Type};
use crate::diagnostic::Diagnostic;
use crate::test_allocation_observer::measure;
use std::collections::{BTreeSet, HashMap, HashSet};
use std::path::Path;

fn receive(source: &str, old: bool) -> (Option<(Type, ParamMode, bool)>, Vec<Diagnostic>) {
    receive_route(source, u8::from(old))
}

fn receive_recursive(source: &str) -> (Option<(Type, ParamMode, bool)>, Vec<Diagnostic>) {
    receive_route(source, 2)
}

fn receive_route(source: &str, receiver: u8) -> (Option<(Type, ParamMode, bool)>, Vec<Diagnostic>) {
    let program = crate::parse(source, Path::new("scoped-recovery.spx")).unwrap();
    let current = program
        .functions
        .iter()
        .find(|function| function.name == "main")
        .unwrap();
    let functions = program
        .functions
        .iter()
        .map(|function| (function.name.as_str(), function))
        .collect::<HashMap<_, _>>();
    let types = TypeTable::new(&program);
    let mut variables = HashMap::new();
    for parameter in &current.params {
        variables.insert(
            parameter.name.clone(),
            Binding {
                contract_local: false,
                traversal_row: None,
                ty: parameter.ty.clone(),
                mode: parameter.mode,
                availability: Availability::Available,
                moved_places: HashMap::new(),
                definitely_partial: HashSet::new(),
                native_unit_discard: false,
                mutable: false,
                active_loans: BTreeSet::new(),
                borrow_origin: None,
            },
        );
    }
    let mut diagnostics = Vec::new();
    let actual = if receiver == 2 {
        // The entire original recursive receiver and all its children remain
        // unchanged, including old inferred types and dependent diagnostics.
        check_expr(
            &program,
            current,
            &current.body,
            &mut variables,
            &functions,
            &types,
            None,
            true,
            &mut diagnostics,
        )
    } else if receiver == 1 {
        super::recovery_legacy::check_expr_iterative_legacy(
            &program,
            current,
            &current.body,
            &mut variables,
            &functions,
            &types,
            None,
            true,
            &mut diagnostics,
        )
    } else {
        super::iterative::check_expr_iterative(
            &program,
            current,
            &current.body,
            &mut variables,
            &functions,
            &types,
            None,
            true,
            &mut diagnostics,
        )
    };
    (
        actual.map(|value| (value.ty, value.mode, value.native_unit)),
        diagnostics,
    )
}

fn source(body: &str) -> String {
    format!("module test.scoped_recovery; @id(\"app.main\") fn main() -> i64 {{ {body} }}")
}

fn codes(diagnostics: &[Diagnostic]) -> Vec<&'static str> {
    diagnostics
        .iter()
        .map(|diagnostic| diagnostic.code)
        .collect()
}

#[test]
fn scoped_refused_let_retains_original_root_and_independent_reads() {
    for body in [
        "let bad = missing; bad",
        "let bad = missing; let alias = bad; alias + bad",
        "let bad = missing; if true { bad } else { bad }",
        "let bad = missing; while false { let alias = bad; 0 } bad",
    ] {
        let source = source(body);
        let (_, old) = receive(&source, true);
        let (_, current) = receive(&source, false);
        assert!(old.len() > current.len(), "{source}: {old:?} / {current:?}");
        assert_eq!(codes(&current), ["SPX-T202"], "{source}: {current:?}");
        assert_eq!(current[0], old[0]);
    }
    let source = source("let bad = missing; bad + unrelated");
    let (_, old) = receive(&source, true);
    let (_, current) = receive(&source, false);
    assert_eq!(codes(&old), ["SPX-T202", "SPX-T202", "SPX-T202"]);
    assert_eq!(codes(&current), ["SPX-T202", "SPX-T202"]);
    assert_eq!(current, [old[0].clone(), old[2].clone()]);
}

#[test]
fn read_before_self_initializer_siblings_and_noncapturing_closures_remain_independent() {
    for body in [
        "let before = later; let later = 1; before",
        "let self_value = self_value; self_value",
        "let ignored = { let ended = missing; 0 }; ended",
        "let ignored = if true { let ended = missing; 0 } else { ended }; 0",
        "let bad = missing; let callback = fn() -> i64 { bad }; 0",
        "let bad = missing; let callback = fn(bad: i64) -> i64 { bad }; 0",
    ] {
        let source = source(body);
        let (_, old) = receive(&source, true);
        let (_, current) = receive(&source, false);
        assert_eq!(current.first(), old.first(), "{source}");
        // Every original error outside the precise refused binding's reads
        // remains byte-for-byte present, including the noncapturing closure.
        for diagnostic in &old {
            if diagnostic.message.contains("unknown value `ended`")
                || diagnostic.message.contains("unknown value `later`")
                || diagnostic.message.contains("unknown value `self_value`")
                    && diagnostic.span == old.first().and_then(|first| first.span)
                || diagnostic.message.contains("unknown value `bad`") && body.contains("fn()")
            {
                assert!(
                    current.contains(diagnostic),
                    "{source}: {diagnostic:?} / {current:?}"
                );
            }
        }
    }
}

#[test]
