#[test]
fn lazy_directory_reuses_ordinals_and_never_scans_authored_function_nodes() {
    let diagnostic = Diagnostic::error("SPX-T202", "missing root", Span::default());
    let diagnostics = vec![diagnostic];
    let mut recovery = Recovery::default();
    recovery.fork(Some(0), 1);
    assert_eq!(recovery.checkpoint(&[]).diagnostics, 0);
    // No successful scope fork acquires backing before the first refusal.
    let (_, empty) = measure(|| {
        let mut directory = Recovery::default();
        for index in 1..1024 {
            directory.fork(Some(index - 1), index);
        }
        drop(directory);
    });
    assert_eq!(empty.allocated, 0);
    assert_eq!(empty.live, 0);
    let checkpoint = recovery.checkpoint(&[]);
    recovery.refused_let(1, "bad", checkpoint, &diagnostics);
    for index in 2..65 {
        recovery.fork(Some(index - 1), index);
    }
    for _ in 0..128 {
        assert!(recovery.reads_refused(64, "bad"));
    }
    assert_eq!(recovery.visited, 128 * 64);
    recovery.fork(Some(0), 1);
    assert!(!recovery.reads_refused(1, "bad"));
    recovery.fork(None, 2);
    assert!(!recovery.reads_refused(2, "bad"));
}

#[test]
fn directory_and_full_receivers_observe_real_acquisition_and_receiving_drop() {
    let diagnostics = vec![Diagnostic::error(
        "SPX-T202",
        "missing root",
        Span::default(),
    )];
    let (_, storage) = measure(|| {
        let mut recovery = Recovery::default();
        let checkpoint = recovery.checkpoint(&[]);
        recovery.refused_let(0, "bad", checkpoint, &diagnostics);
        for index in 1..65 {
            recovery.fork(Some(index - 1), index);
        }
        for _ in 0..128 {
            assert!(recovery.reads_refused(64, "bad"));
        }
        drop(recovery);
    });
    assert!(!storage.invalid);
    assert!(storage.allocated > 0);
    assert_eq!(storage.live, 0);
    assert_eq!(storage.allocated, storage.freed);
    for body in [
        "let bad = missing; let alias = bad; alias + bad",
        "let bad = missing; let callback = fn() -> i64 { bad }; 0",
    ] {
        let source = source(body);
        for old in [true, false] {
            let (_, receiver) = measure(|| {
                drop(receive(&source, old));
            });
            assert!(!receiver.invalid, "old={old}: {receiver:?}");
            assert_eq!(receiver.live, 0, "old={old}: {receiver:?}");
            assert_eq!(receiver.allocated, receiver.freed);
        }
    }
}

//! Annotation refusal is an expected-type explanation, never a replacement
//! checked type, owner, place state, or lexical loan.
use super::{codes, receive, source};
use crate::ast::{ParamMode, Type};
use crate::diagnostic::Diagnostic;
use std::path::Path;

const CALLS: &str = r#"
@id("bool.id") fn bool_id(value: bool) -> bool { value }
@id("bool.consume") fn f_bool(value: bool) -> i64 { 0 }
@id("string.consume") fn f_string(value: string) -> i64 { 0 }
@id("bytes.consume") fn consume_bytes(value: own Bytes) -> i64 { 0 }
"#;

fn module(body: &str) -> String {
    format!(
        "module test.refusal_dependency; {CALLS} @id(\"app.main\") fn main() -> i64 {{ {body} }}"
    )
}

fn full(source: &str, old: bool) -> Vec<Diagnostic> {
    let program = crate::parse(source, Path::new("refusal-dependency.spx")).unwrap();
    if old {
        crate::source_verify::declaration::old::verify(&program)
    } else {
        crate::source_verify::verify(&program)
    }
}

fn selected(source: &str, old_codes: &[&str], current_codes: &[&str]) {
    let old = full(source, true);
    let current = full(source, false);
    assert_eq!(codes(&old), old_codes, "old: {source}\n{old:?}");
    assert_eq!(
        codes(&current),
        current_codes,
        "current: {source}\n{current:?}"
    );
    assert_eq!(current.first(), old.first(), "original root: {source}");
    let mut remaining = old.iter();
    for diagnostic in &current {
        assert!(
            remaining.any(|original| original == diagnostic),
            "lost exact original diagnostic provenance: {source}: {diagnostic:?}"
        );
    }
}

